quests[32363] = { id = 32363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kun-Lai-Expedition", description = "Ich habe noch eine Nachricht für Euch von Oberhäuptling Bluthuf.\n\nAnscheinend habt Ihr ihn beeindruckt.\n\nEr reist mit der Vorhut des Kriegshäuptlings zum Kun-Lai-Gipfel im Norden. Sie haben einen Außenposten errichtet, den Garrosh'arvorstoß, östlich von Einfass.\n\nIhr solltet ihn besser nicht warten lassen. Sprecht mit Tak-Tak, um schnell dorthin zu gelangen.", sourceObjective = "Findet Baine Bluthuf beim Garrosh'arvorstoß. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32364] = { id = 32364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandarische Medizin", description = "Während ich im Tal war ist mir ein uraltes pandarisches Rezept für Wein der Erinnerungen untergekommen. Ich glaube, dass dieses Gebräu einige hilfreiche Informationen aus Shan Kien hervorlocken kann.\n\nIch werde hier gebraucht, deswegen muss ich Euch bitten, die Zutaten für mich zu finden.\n\nDas Rezept befindet sich in einem Buch hinter mir, bei meinen anderen Dingen.", sourceObjective = "Findet das Rezept für den Wein der Erinnerungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32365] = { id = 32365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Epilogue Complete" }
quests[32366] = { id = 32366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schlückchen Feuer", description = "6 Feuerwein von Ruqin. Dieser starke Likör hilft, den Verstand zu entspannen, was die Erinnerung an Vergangenes ermöglicht.\n\n<Am Rand wurde noch eine Notiz hinzugefügt.>\n\n(Merke: Kann zu einem furchtbaren Kater führen.)", sourceObjective = "Sammelt 6 Feuerwein von Ruqin.", sourceObjectiveStatus = "unverified-source-field" }
quests[32367] = { id = 32367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen Yakmilch", description = "3 Portionen frische Yakmilch. Gut für Zähne und Knochen. Erlaubt es Trinkenden, aus ihrem Traumzustand zurückzukehren.\n\n<Die inzwischen bekannte Handschrift hinterlässt an dieser Stelle eine kryptische Bemerkung.>\n\n(Warum sehen alle Yaks gleich aus?!)", sourceObjective = "Sammelt 3 Portionen frische Yakmilch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32368] = { id = 32368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wein der Erinnerungen", description = "Die Tinktur ist fertig. Jetzt trinkt sie.", sourceObjective = "Trinkt den Wein der Erinnerungen und werdet Zeuge von Shan Kiens Vergangenheit.", progress = "Was habt Ihr gesehen?", completion = "Was habt Ihr gesehen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[32369] = { id = 32369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Vergangenheit" }
quests[32370] = { id = 32370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kun-Lai-Expedition", description = "Ruhm der Allianz, {class}. Wir machen im Konflikt mit der Horde in der Krasarangwildnis Fortschritte, wenn auch nur langsam.\n\nWährend wir hier die Front halten, müsst Ihr woanders zuschlagen – auf eine Weise, die unseren Feind direkt im Herzen trifft.\n\nUnser Informant vom SI:7, Agent Connelly, hat Nachricht gegeben, dass eine Vorhut der Horde in die nördlichen Gefilde des Kun-Lai-Gipfels zieht.\n\nGeht sofort. Nehmt mit Agent Connelly Kontakt auf und findet heraus, was dort vor sich geht.\n\nSprecht mit Fennie dort drüben, um einen Flug zu organisieren.", sourceObjective = "Findet Agent Connelly auf dem Grummelbasar. Sprecht mit Fennie Hornsturz in der Löwenlandung bezüglich einer Transportmöglichkeit.", completion = "<Ihr seht zweimal hin, als der Pandaren plötzlich mit Connellys Stimme spricht.>\n\nWar auch langsam Zeit, Kleiner! Ich hab schon auf Euch gewartet.\n\nDiese Pandaren sind gute Leute, aber einen Martini können sie nicht mixen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32371] = { id = 32371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wein der Erinnerungen", description = "<Die Funkverbindung ist kurz gestört, dann spricht Agent Connelly weiter.>\n\nJetzt kommt die wahre Herausforderung, <Junge/Mädchen>. \n\nBegebt Euch in die Mitte des Lagers und versucht, zu belauschen, was gesagt wird.", sourceObjective = "Nutzt die Kor'kron-Verkleidung, um das Lager zu betreten. Trinkt dann den Wein der Erinnerungen und werdet Zeuge von Shan Tiens Vergangenheit.", completion = "Schon zurück, Grünschnabel? Was habt Ihr gelernt?", sourceObjectiveStatus = "unverified-source-field" }
quests[32372] = { id = 32372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Unterwerfung", description = "Die Kor'kron sind die besten und treuesten Soldaten des Kriegshäuptlings. Ihre Anwesenheit hier bedeutet, dass Garrosh einen Aufstand befürchtet.\n\nVol'jin und sein Volk sind genauso Teil der Horde wie jeder Orc.\n\nWir müssen die Belagerung beenden und die Trolle befreien. Es schmerzt mich, dies zu sagen, aber Ihr müsst so viele der Kor'kron töten, dass die Trolle ihre Stadt zurückerobern können. Danach trefft mich in der Dunkelspeerfeste und wir fordern ihren Offizier direkt heraus.", sourceObjective = "Tötet 10 Aufseher der Kor'kron, 5 Unterwerfer der Kor'kron und Gul'tar den Unterwerfer.", progress = "Wie konnte das nur passieren? Der Begriff \"Ehre\" scheint für diese Orcs nicht die geringste Bedeutung zu tragen.", completion = "Die Orcs haben sich geändert. Meine Horde hat sich geändert. Töte ich meine Orckameraden, bis es wieder \"meine\" Horde ist? Habe ich das Recht meine Horde dazu zu zwingen, wieder das zu werden, was sie einst war?\n\nDies sind Zeiten der Not. Doch zuerst muss ich mich um Vol'jins Leute kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[32373] = { id = 32373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was den Anführer ausmacht", description = "Die Pandarenkampagne ist inzwischen fortgeschritten. Die Allianz ist mit der versammelten Macht Ihrer Marine an der Küste gelandet. Euer König möchte der Hordeaggression in diesem neuen Land Einhalt gebieten.\n\nGarrosh Höllschrei treibt die Horde geradeheraus in den Kampf, aber König Varian Wrynn kann ich nicht so leicht durchschauen. Habt Ihr einen Augenblick Zeit? Ich würde gern über diesen Anführer von Euch sprechen.", sourceObjective = "Sprecht mit Furorion in der Taverne im Nebel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32374] = { id = 32374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzliches Anliegen", description = "Mein Ziel ist das schnelle Ende dieses kostspieligen Krieges. Beweist mir, dass die Allianz es verdient, zu gewinnen. Zeigt mir Euer Können auf dem Schlachtfeld.\n\nIhr werdet nicht gegen eine abstrakte Macht wie das Sha kämpfen, sondern Euren Gegnern direkt gegenüberstehen.\n\nWerdet Ihr siegen?", sourceObjective = "Tötet Hordetruppen entlang der südlichen Küsten der Krasarangwildnis bis Ihr beim Schwarzen Prinz einen respektvollen Status erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32375] = { id = 32375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und ein wenig davon", description = "100 Braunkappenpilze. Müssen frisch von einem feuchten, dunklen Ort geerntet werden.\n\n<Am Rand der Seite wurde ein handgeschriebener Kommentar hinzugefügt.>\n\nPilze sind gut für die Gesundheit! (Oder sie bringen Euch um, verursachen schlimme Krankheiten, Ausschläge, Halluzinationen oder Durchfall. Merke: MUSS AUFPASSEN, wenn ich wilde Pilze sammle!)", sourceObjective = "Sammelt 100 Braunkappenpilze.", sourceObjectiveStatus = "unverified-source-field" }
quests[32376] = { id = 32376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Tal!", description = "Diese versiegelte Nachricht wurde für Euch geschickt, zusammen mit dem dringenden Befehl, ins Tal der Kaiser auf dem Kun-Lai zu reisen.\n\nEs scheint ernst zu sein. Ich an Eurer Stelle würde nicht zögern.\n\nSprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.", sourceObjective = "Findet Euren \"Freund aus Silbermond\" im Tal der Kaiser. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", completion = "Ah, gut. Ihr seid gekommen.\n\nEs tut mir wirklich leid, eine solch rätselhafte Nachricht geschickt zu haben, aber Garrosh hat kaum mehr Vertrauen zu uns. Ich will nicht, dass eine unüberlegte Tat seinerseits alles beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32377] = { id = 32377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Kor'kron in unserer Mitte", description = "Garrosh ist darauf versessen, die Götterglocke zu finden. Es würde mich nicht überraschen, wenn er den gesamten Kun-Lai auseinandernimmt, um das Artefakt zu finden.\n\nDer Kriegshäuptling hat ein Treffen im Garrosh'arvorstoß im Norden einberufen.\n\nIch muss hierbleiben, um alle Truppenbewegungen zu überwachen, also müsst Ihr in das Lager eindringen und die Diskussion belauschen.\n\nGeht zum Garrosh'arvorstoß und stehlt Teile einer Rüstung der Kor'kron von Häschern, Ehrenwachen und Spähern.\n\nNehmt diesen Funkkopfhörer fürs Ohr an Euch, aber nehmt nicht mit mir Kontakt auf... ich werde mit Euch Kontakt aufnehmen.", sourceObjective = "Erlangt einen Helm der Kor'kron, eine Rüstung der Kor'kron und ein Paar Stiefel der Kor'kron und stellt dann aus ihnen eine Kor'kron-Verkleidung her.", progress = "Genau in dem Moment, wo Ihr die Kor'kron-Verkleidung betrachtet, knistert der Funkkopfhörer in Eurem Ohr.", completion = "<Agent Connellys Stimme erreicht Euch über Funk.>\n\nHey, Ihr seid gut! Wusste ich doch, dass diese Kor'kron kein Problem für Euch darstellen würden. Hätte es selbst nicht besser machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[32378] = { id = 32378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg bereiten", description = "Eins nach dem anderen. Wenn wir den Anführer gefangen nehmen wollen, müssen wir die Zahl seiner Agenten verringern.\n\nSeid vorsichtig. Diese Mogu sind besonders gefährlich – es scheint, als ob sie das Sha in einer uns bisher unbekannten Weise beeinflussen können.", sourceObjective = "Tötet 10 Korunmogu.", completion = "Gut. Wir sollten jetzt bereit für unseren Zug sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32379] = { id = 32379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe der Korun", description = "Ich bin nicht bereit, noch mehr unseres Volkes im Kampf gegen einen Feind, den wir weder kennen noch verstehen, zu opfern.\n\nSchaut bitte, ob ihr in diesem Gebiet irgendwelche Hinweise findet, die besagen, wer diese \"Korunmogu\" sind. Nur für den Fall, dass der Einsatz nicht wie geplant abläuft.", sourceObjective = "Findet das Dokument 'Das Vermächtnis der Korun' im Tal der Kaiser und besorgt das versiegelte Artefakt der Korun und die Korunbefehle von den Mogu der Korun.", progress = "Habt Ihr etwas über die Mogu herausgefunden?", completion = "Gut. Hier ist einiges an Informationen verborgen...\n\nIch werde die Archäologische Akademie beauftragen, eine Untersuchung durchzuführen. Bestimmt können wir so mehr Geheimnisse über diese Mogu der Korun enträtseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32380] = { id = 32380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beste hier", description = "Wir werden Hilfe benötigen, wenn wir herausfinden wollen, was Garrosh mit Pandaria vorhat.\n\nIch denke da an jemand Bestimmten, aber er wird nicht leicht zu überzeugen sein.\n\nAgent Connelly glaubt zwar, er sei im Ruhestand, aber den SI:7 verlässt man nicht einfach so. Schon seit Monaten folgt ihm einer unserer Geheimagenten.\n\nMomentan tarnt er sich als ein Profiglücksspieler in Bizmos Boxbar. Hat irgendetwas mit der Begleichung einer alten Rechnung zu tun.\n\nTrefft Euch mit unserem Geheimagenten in der Kampfgilde.", sourceObjective = "Meldet Euch bei Geheimagentin Townsley in Bizmos Boxbar auf der Sturmwindseite der Tiefenbahn.", progress = "Ihr glaubt also, Ihr könntet Connelly aus dem Ruhestand zurückholen? Viel Glück!", completion = "Connelly zu folgen war, gelinde gesagt, ziemlich interessant. Er ist ein Meister der Tarnung!\n\nIhn dazu zu bewegen, mit Euch zu gehen, wird nicht die Schwierigkeit sein, {class}, sondern herauszufinden, wer von diesen munteren Personen er ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[32381] = { id = 32381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Spion fängt", description = "Nun, ich könnte Euch sagen, wer Connelly ist, aber das wäre zu einfach! Um einen Spion zu erwischen, müsst Ihr wie ein Spion denken.\n\nZunächst müsst Ihr den Test bestehen!\n\nDie kleinsten Dinge können viel über eine Person aussagen. Der Teufel steckt im Detail.\n\nIch werde Euch ein Getränk geben, das Ihr serviert. Ich werde Euch ein kleines Detail darüber verraten, was der Empfänger trägt. Alles andere liegt an Euch.\n\nSeid vorsichtig, wem Ihr etwas zu trinken gebt. Die Leute hier können ziemlich ungehalten werden, wenn Ihr ihnen das falsche Getränk hinstellt!", sourceObjective = "Bringt das rosarote Murmeltier, die Mogumelonenüberraschung und den rostigen Dolch zu den richtigen Gästen.", progress = "Als Barkeeper lernt man, auf Details zu achten.", completion = "Ihr habt ein gutes Auge, {class}! Ich glaube, Ihr seid jetzt bereit, um Connelly zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32382] = { id = 32382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfekt getarnt", description = "Agent Connelly konnte Garroshs Lager auf dem Kun-Lai-Gipfel infiltrieren und beobachtet alles, was dort vor sich geht! \n\nEr hat spezifisch nach Euch gefragt, um ihm bei der Beschaffung wichtiger Informationen zu helfen.\n\nEr hat eine Tarnung für Euch geschickt. Vergesst nicht, sie anzulegen, bevor Ihr Euch dem Lager nähert! Es wird ganz gewiss schwer bewacht.\n\nEr ist sich sicher, dass Ihr ihn erkennen werdet, wenn Ihr ihn seht. Sagte, Ihr hättet ein scharfes Auge fürs Detail...\n\nSprecht mit Fennie dort drüben und sie bringt Euch hin.", sourceObjective = "Trefft Connelly auf dem Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung bezüglich einer Transportmöglichkeit.", completion = "Ihr seid gerade rechtzeitig gekommen. Den von mir gesammelten Informationen zufolge ist Garrosh auf der Spur eines uralten mächtigen Moguartefakts.\n\nWenn wir herausfinden, wonach er sucht, können wir verhindern, dass er es findet!\n\nWir müssen schnell handeln, um so viel Informationen wie möglich zu sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32383] = { id = 32383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwanzt", description = "Ich habe einige Wanzen im Lager verteilt, aber mehr schaden nie.\n\nIch habe sie so getarnt, dass sie wie Statuen aussehen. Zwischen all den anderen Artefakten fallen sie überhaupt nicht auf.\n\nEure Tarnung sollte es Euch ermöglichen, Euch frei im Lager zu bewegen. Bleibt nur dem Hund fern und haltet Euch nicht in Garroshs Nähe auf! Nero und Garrosh werden Eure Tarnung durchschauen!\n\nIch kann Euch nicht helfen, wenn Ihr erwischt werdet. Ich darf die Mission nicht gefährden!", sourceObjective = "Verwanzt das große Zelt in der Nähe der kleinen Zelte sowie die Vorräte mit clever getarnten Wanzen.", completion = "Gut gemacht! Die kleinen Dinger werden regelmäßig unterschätzt, und es ist regelmäßig ein großer Fehler!", sourceObjectiveStatus = "unverified-source-field" }
quests[32384] = { id = 32384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Anführer gefangen nehmen", description = "Gut, es ist an der Zeit, zuzuschlagen. Geht zum Grab der Schatten, schwächt ihn und nehmt ihn gefangen.\n\nIch bleibe hier, falls Garrosh eintrifft. Ich werde versuchen, ihn aufzuhalten, sodass wir unsere Beute an uns nehmen können, bevor er sie zerstört.\n\nBeeilt Euch!", sourceObjective = "Schwächt und ergreift Shan Kien am Grab der Schatten am Kun-Lai-Gipfel.", progress = "Schnell, {name}!", completion = "Wir haben unser Ziel gefangen nehmen können.\n\nIch bin mir allerdings nicht sicher, was wir als Nächstes tun sollen. Ich werde mich mit den Anführern unserer Verbündeten in Verbindung setzen, um zu erfahren, ob sie vielleicht Ideen haben, denn ich glaube nicht, dass unsere arkanen Talente unserem Mogugefangenen seine Geheimnisse entlocken werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32388] = { id = 32388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führungswechsel", description = "Es gibt einen General der Orcs, den ich schon länger beobachte. Kriegsfürst Blutheft hat sich bei Garrosh Höllschrei eingeschmeichelt, indem er einen Vorstoß der Allianz im Südlichen Brachland zurückgeschlagen hat. Jetzt hat er sich in der Herrschaftsfeste verschanzt.\n\nIch bezweifle, dass die Allianz ihn besiegen kann. Aber... Ihr habt mich schon einmal eines Besseren belehrt.\n\nWenn Ihr ihn ausschalten wollt, bringt Freunde mit. Viele Freunde.", sourceObjective = "Tötet Kriegsfürst Blutheft in der Herrschaftsfeste in der Krasarangwildnis. Ihr werdet eine Gruppe benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32389] = { id = 32389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Löwe brüllt", description = "Dies ist ein weltweiter Krieg, {name}. Er ist bis nach Pandaria gelangt und hat Krisenherde in Kalimdor und den Östlichen Königreichen in Brand gesetzt. Wie verhaltet Ihr Euch in einem organisierten Kampf? Das würde ich gern selbst sehen.\n\nIch erwarte Euren Bericht von der Front.", sourceObjective = "Gewinnt Kämpfe im Tempel von Katmogu und in der Silberbruchmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32390] = { id = 32390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Rudelführers", description = "{class}, durch Eure Augen konnte ich die Kämpfe entlang der Küste und den epischen Verlauf der Gefechte in der ganzen Welt verfolgen. Ihr wart sehr geduldig... und habt mir viele Informationen geliefert.\n\nAußerdem habe ich Euren König im Auge behalten. Wollt Ihr wissen, was ich erfahren habe?", sourceObjective = "Sprecht mit Furorion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32391] = { id = 32391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Korun", description = "Garrosh hat eine Hundertschaft Kavalleristen entsandt, um die nördliche Küste des Kun-Lai-Gipfels nach einer Mogugruft abzusuchen, wie Ihr sie in Shan Kiens Erinnerungen gesehen habt.\n\nEiner seiner Leute hat die Götterglocke aufgespürt.\n\nKlingenmeister Ishi führt eine Vorhut an, um die Glocke in Sicherheit zu bringen.\n\nGeht und helft ihm. Verteidigt das Artefakt vor allen, die es wagen, sich Euch in den Weg zu stellen!\n\nSprecht umgehend mit Tak-Tak. Er kann euch dort hinbringen.", sourceObjective = "Sprecht mit Ishi in den Ruinen von Korun am Kun-Lai-Gipfel. Sprecht mit Tak-Tak bei der Herrschaftsfeste für einen Transport dorthin.", completion = "Die Allianz war vor uns hier? Wie konnte das passieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[32392] = { id = 32392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Götterglocke", description = "Wenn die Allianz glaubt, dass sie uns die Götterglocke stehlen kann, irrt sie sich gewaltig!\n\nSie ist in den Gewölben unter uns nach wie vor in sicherer Verwahrung.\n\nDass die Allianz es wagt, sich uns entgegenzustellen, wird sie mit dem Tod bezahlen.\n\nLos, {class}. Zeigen wir ihr, wie falsch sie liegt.", sourceObjective = "Tötet Sarannha Himmelsgleve.", completion = "Darnassus, soso!\n\nDie Allianz glaubt, sie habe heute den Sieg davongetragen. Jetzt, da ihre Arroganz größer ist als je zuvor, haben wir eine vortreffliche Gelegenheit, ihr den Preis vor der Nase wegzuschnappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32393] = { id = 32393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Korun", description = "Die Zeit ist reif für unseren bislang kühnsten Schachzug, {name}.\n\nDa Ihr Informationen zum Versteck der Götterglocke ans Licht bringen konntet, haben wir eine Elitemannschaft aufgestellt, die das Artefakt umgehend ausgraben wird.\n\nKommandantin Sarannha Himmelsgleve wird die Expedition in die nördlichsten Winkel des Kun-Lai-Gipfels anführen.\n\nMeldet Euch sofort zur Stelle und setzt all Eure Fertigkeiten ein, um dieses Vorhaben zum Erfolg zu führen.\n\nViel Glück, {class}. Ich muss wohl nicht betonen, wie wichtig diese Mission für die Allianz ist.\n\nSprecht mit Fennie. Sie wird Euch schnell dort hinbringen.", sourceObjective = "Sprecht mit Sarannha Himmelsgleve in den Ruinen von Korun am Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung für einen Transport dorthin.", completion = "Wir haben die Türen soeben aufgesprengt, {class}. Ihr kommt gerade rechtzeitig, um der Ausgrabung beizuwohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32394] = { id = 32394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Götterglocke", description = "Was uns dort unten erwartet, weiß der Henker, also werde ich den ersten Spähtrupp persönlich anführen.\n\nWenn Euer Bericht stimmt, dann haben die Korunmogu die Götterglocke in den Kammern direkt unter uns versteckt.\n\nSie werden ein solch kostbares Artefakt wohl kaum unbewacht lassen.\n\n<Ein so fähiger/Eine so fähige:c> {class} wie Ihr wäre mir als Rückendeckung eine große Hilfe. Gebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Tötet Schreckenswirker Avartu und bergt die Götterglocke.", completion = "Hervorragende Arbeit, {name}. Ich wage mir die Gräueltaten kaum auszumalen, die Garrosh verüben würde, wenn die Glocke in seine Hände fiele.\n\nHeute haben wir der Allianz eine sichere Zukunft erkämpft. Ich werde dafür sorgen, dass die Glocke sicher nach Darnassus gelangt.\n\nIch werde Eure Taten vor dem König zu rühmen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32395] = { id = 32395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Avartu gesehen" }
quests[32396] = { id = 32396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncompletable Binding Quest [DND]" }
quests[32397] = { id = 32397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es wird ihm gar nicht auffallen", description = "Ich habe beobachtet, wie Garrosh und dieser Blutelf von der Archäologischen Akademie eine Art Tagebuch mit sich herumtragen.\n\nDas Tagebuch ist immer in Reichweite. Es muss wichtig sein!\n\nWenn Ihr es schafft, für eine entsprechende Ablenkung zu sorgen, könnt Ihr das Tagebuch vielleicht vom Tisch stehlen.\n\nDiese Yaks könnten die Lösung sein: Gebt einem von ihnen einen Klaps und den Rest machen sie dann schon allein.\n\nIhr müsst nur bereit sein, schnell zu handeln!", sourceObjective = "Sorgt für eine Ablenkung im Lager und stehlt das verwitterte Tagebuch.", progress = "Was habt Ihr gefunden?", completion = "Puh! Das war knapp! Ich habe aber keine Sekunde an Euch gezweifelt.\n\nLasst mich jetzt das Tagebuch ansehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[32398] = { id = 32398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Glocke spricht", description = "Eure Bemühungen kulminieren in diesem Augenblick, {class}.\n\nKriegshäuptling Garrosh sammelt die besten Champions der Horde am Kun-Lai-Gipfel, damit sie dem Läuten der Götterglocke beiwohnen können.\n\nIhr habt Euch das Recht zur Teilnahme redlich verdient.\n\nGeht jetzt. Heute ist der Beginn der neuen Horde.\n\nSprecht mit Tak-Tak. Er sollte eine Transportmöglichkeit für Euch organisieren können.", sourceObjective = "Findet Malkorok bei der Kaiserhöhe. Sprecht mit Tak-Tak bei der Herrschaftsfeste für eine Transportmöglichkeit.", completion = "Ich habe mich schon gefragt, wann Ihr kommen würdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32399] = { id = 32399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atem der dunkelsten Schatten", description = "Es ist so weit, {name}. Wir sind weit gereist, um diesen Moment zu erleben.\n\nHeute wird unser Kriegshäuptling Garrosh Höllschrei die Geschichte unseres Volkes für immer verändern.\n\nHeute werden wir Zeugen der Geburt von Garroshs Horde!\n\nSorgt dafür, dass die Zeremonie durch nichts unterbrochen wird!", sourceObjective = "Erlebt das Läuten der Götterglocke.", progress = "Wir können uns nicht auf Schicksal oder Vorsehung verlassen. Wir müssen unsere eigene Zukunft gestalten... die Zukunft, die WIR verdienen!", completion = "Sie mögen die Götterglocke zerstört haben, ich aber habe das Leben des verlorenen Sohnes der Allianz genommen!\n\nGenau das hätte mein eigener Vater von mir erwartet.\n\nDieser Sieg mag teuer gewesen sein, das tut jedoch wenig zur Sache.\n\nIch werde andere Wege finden, meine Feinde zu vernichten und der Horde Ruhm zu bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32400] = { id = 32400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Glocke spricht", description = "Die Streitkräfte der Horde sammeln sich in großer Zahl an der Kaiserhöhe, hoch in den Bergen des Kun-Lai-Gipfels.\n\nDas Gebiet ist ein uralter Palast der Mogu und bestimmt eine Quelle unermesslicher Macht.\n\nDas kann nur eins bedeuten: Garrosh wird die Götterglocke benutzen, und Anduin... und der Schlaghammer der Harmonie... sind beide verschollen.\n\nDer dumme Junge ist zweifellos allein nach Norden aufgebrochen.\n\nIch habe keine Zeit, einen Elitetrupp zusammenzustellen, um ihn zurückzubringen. Ihr müsst Anduin aufhalten.\n\nFennie kann Euch hinbringen.", sourceObjective = "Findet Anduin bei der Kaiserhöhe. Sprecht mit Fennie Hornsturz in der Löwenlandung für eine Transportmöglichkeit.", completion = "{name}! Genau der {class}, den ich zu sehen hoffte. Ihr könntet nicht gelegener kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32401] = { id = 32401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atem der dunkelsten Schatten", description = "Garrosh ist gleich da drüben und wird die Glocke jeden Moment läuten.\n\nUns bleibt keine Zeit, auf die Armee meines Vaters zu warten. Das ist unsere einzige Chance, ihn aufzuhalten!\n\nIch werde versuchen, an seine Vernunft zu appellieren, ehe ich auf die Verwendung des Schlaghammers der Harmonie zurückgreife.\n\nGreift an, sobald Ihr so weit seid, {name}. Ich bin direkt hinter Euch.", sourceObjective = "Besiegt Ishi und zerstört die Götterglocke.", completion = "<Anduin sieht wie eine zerknautschte Puppe aus. Er liegt regungslos da, nur die kühle Luft spielt mit seinem goldblonden Haar.>\n\n<Ihr sitzt eine Weile bewegungslos da, bis Euch die Kälte in die Knochen fährt. Die Glocke ist zerstört, die Stille jedoch ohrenbetäubend.>\n\n<Aus dem Augenwinkel seht Ihr, wie die Hand des Jungen leicht zuckt. Ihr lehnt Euch über ihn. Er atmet – wenn auch nur ganz schwach! Anduin ist am Leben!>", sourceObjectiveStatus = "unverified-source-field" }
quests[32402] = { id = 32402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lage in Dalaran", description = "Die Nachtelfen haben erfahren, dass die Götterglocke gestohlen wurde. Das hatten wir erwartet.\n\nAußerdem haben sie noch herausgefunden, dass die \"neutralen\" Sonnenhäscher von Dalaran daran beteiligt waren. Jetzt haben wir ein Problem.\n\nIhr müsst nach Dalaran aufbrechen. Sprecht mit Kromthar, um den Transport zu arrangieren. Ihr werdet Großmagister Rommath aufsuchen, sobald Ihr dort seid.", sourceObjective = "Sprecht mit Kromthar, um Euch nach Dalaran transportieren zu lassen.", completion = "Ihr seid also angekommen. Heute ist kein guter Tag, ein Mitglied der Horde in Dalaran zu sein.\n\nJaina hat die Verstoßung aller Sonnenhäscher angeordnet. Wir beide werden so viele retten, wie wir nur können - einschließlich Erzmagier Aethas Sonnenhäscher selbst - und dann so schnell wie möglich hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32403] = { id = 32403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Station: Kanalisation", description = "Verglichen mit dem Rest der Stadt herrscht in diesem Abschnitt der Kanalisation relative Ruhe. Und das ist gut so - wo es friedlich ist, lassen sich mehr Sonnenhäscher befreien, als dort, wo der Krieg tobt.\n\nFindet so viele Bürger wie möglich. Sagt ihnen, dass es hier nicht sicher ist und dass sie umgehend aus der Stadt fliehen müssen.\n\nUnd haltet Euch vom Silberbund fern. Wir wollen keinen Aufruhr auslösen, wo es sich vermeiden lässt. Zumindest noch nicht jetzt.", sourceObjective = "Evakuiert 9 Bürger der Sonnenhäscher.", completion = "Stoßen wir weiter vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32404] = { id = 32404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewalt in der Arena", description = "Wie ich vermutete, ist die Lage da oben noch schlimmer. Der Silberbund greift skrupellos unschuldige Sonnenhäscher an!\n\nDas dürfen wir nicht zulassen. Wenn unsere erste Direktive auch lautet, Aethas Sonnenhäscher zu befreien, müssen wir dabei so viele Blutelfen wie möglich schützen.\n\nIch werde weiter die Lage auskundschaften. Kämpft tapfer, {class}!", sourceObjective = "Tötet 6 Vollstrecker und 4 Zauberschützen des Silberbunds.", completion = "So viel Blutvergießen! Und das an einem Ort des Friedens!\n\nDieses Mal ist Jaina zu weit gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32405] = { id = 32405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Silberbunds", description = "Jeder Sonnenhäscher, den Jaina aus dieser Stadt vertreibt, ist eine neue Klinge, die im Namen der Horde kämpft. Für UNS.\n\nIch werde losziehen, um noch mehr starke Elfen zu versammeln. Ihr habt Euer Können im Kampf unter Beweis gestellt - geht und kümmert Euch um diesen Widerling auf dem Schwarzmarkt.\n\nWenn Ihr fertig seid, treffen wir uns an der Rampe und bereiten uns darauf vor, nach oben zu gehen.", sourceObjective = "Tötet Sorin Magierhand.", completion = "Die erste Etappe unserer Mission wäre beendet. Das war der einfache Teil.\n\n<Rommath atmet tief und langsam ein, ehe er fortfährt...>", sourceObjectiveStatus = "unverified-source-field" }
quests[32406] = { id = 32406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein taktischer Angriff", description = "Wenn wir dort oben überleben wollen, brauchen wir eine Operationsbasis.\n\nIch werde versuchen, das Zentrum der Stadt zu erobern. Ein riskantes Vorhaben, doch ich hoffe, dass Jaina und der Silberbund nicht damit rechnen.\n\nBleibt an meiner Seite, {name}.", sourceObjective = "Folgt Großmagister Rommath ins Zentrum von Dalaran.", completion = "Jetzt gilt es schnell zu handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32407] = { id = 32407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handelsmarkt der Magier" }
quests[32408] = { id = 32408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Festung des Silberbunds", description = "Ich habe aus verlässlicher Quelle erfahren, dass Erzmagier Aethas Sonnenhäscher in der Silbernen Enklave, der Heimat des Silberbunds, festgehalten wird. Arkanistin Rathaella hat ihn dort in Gewahrsam genommen.\n\nDie meisten Agenten des Bunds sind derzeit damit beschäftigt, die Sonnenhäscher abzuschlachten. Das ist eine gute Gelegenheit für uns. Tötet Rathaella und befreit Aethas aus seiner Gefangenschaft.", sourceObjective = "Tötet Arkanistin Rathaella.", completion = "Wir werden uns weiterhin um die Rettung der Sonnenhäscher bemühen. Vielleicht erfahren wir dabei, wo Aethas ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[32409] = { id = 32409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wahre Gesicht der Kirin Tor", description = "Jeglicher Vorwand der Kirin Tor, eine \"neutrale\" Organisation zu sein, ist jetzt offiziell widerlegt. Ich höre, dass Jaina Truppen der Allianz in der Nähe von Antonidas' Denkmal in Bereitschaft hält.\n\nDas Gebiet ist frei von Sonnenhäschern, doch angesichts der unverhohlenen Vetternwirtschaft der Kirin Tor kocht mir noch immer das Blut in den Adern.\n\nGeht und stattet dem Denkmal einen Besuch ab, {name}... und verpasst diesen Hundesöhnen der Allianz auf dem Weg eine hübsche Abreibung.", sourceObjective = "Tötet Leutnant Corwin und 10 seiner Soldaten.", completion = "Ich danke Euch dafür, {name}.\n\nMir ist nicht wohl dabei, offen gegen die Hochelfen des Silberbunds zu kämpfen... doch des Tötens der Allianz werde ich nie müde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32410] = { id = 32410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus Landeplatz", description = "Wir können so viele Sonnenhäscher retten, wie wir wollen, aber wenn sie nicht entkommen können, ist es kaum sinnvoll.\n\nDer Silberbund wird die Drachenfalken der Sonnenhäscher ganz gewiss unter seine Kontrolle bringen oder gar töten. Verhindert das.", sourceObjective = "Befreit 6 Drachenfalken der Sonnenhäscher.", completion = "Gut gemacht, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32411] = { id = 32411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verbleibenden Sonnenhäscher", description = "Es werden noch immer einige wichtige Vertreter der Sonnenhäscher vermisst. Es wäre gut möglich, dass man sie in Sonnenhäschers Zuflucht überrascht hat.\n\n<Rommath überreicht Euch ein offensichtlich von Blutelfenhand gefertigtes Artefakt.>\n\nDort wimmelt es nur so von Truppen des Silberbunds. Ihr müsst Euch Zutritt verschaffen, die Träne benutzen, um diese wichtigen Persönlichkeiten zu evakuieren, und dann fliehen.\n\nBleibt am Leben, {name}.", sourceObjective = "Wendet die Träne der Sin'dorei auf Uda das Biest, den Hocharkanisten Savor, Magister Hathorel, Magister Surdiel und Magistrix Vesara an.", completion = "Hervorragend. Sie sollten in Silbermond auf unsere Rückkehr warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32412] = { id = 32412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Ort", description = "Wir haben alle Orte abgesucht, an denen er sein könnte, bis auf einen: die Violette Zitadelle.\n\nFindet heraus, ob Erzmagier Aethas in der Zitadelle festgehalten wird, {name}. Vielleicht haben wir Glück. Und wenn nicht... haben wir heute zumindest ein paar Leben retten können.", sourceObjective = "Tötet den Magierkommandanten Zuros und flieht dann aus Dalaran.", completion = "Ist das... {name}? Was geht hier vor?", sourceObjectiveStatus = "unverified-source-field" }
quests[32413] = { id = 32413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Krasarang", description = "Wem Ihr Eure Treue auch geschworen haben mögt - Rommath und mir, Garrosh oder wem immer sonst - Tatsache ist: Eure heutigen Taten zeugen von wahrem Heldenmut.\n\nIch kann gerne den Rücktransport in die Krasarangwildnis für Euch arrangieren. Sprecht mit mir, wenn Ihr eine Passage zurück nach Pandaria wünscht, {name}.", sourceObjective = "Meldet Euch bei General Nazgrim bei der Herrschaftsfeste in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32414] = { id = 32414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Darnassus?", description = "Wie Ihr wisst, haben unsere Nachtelfenverbündeten die Götterglocke, die Ihr geborgen habt, zur sicheren Verwahrung und Untersuchung nach Darnassus gebracht. Vor Kurzem haben sie einige hochgeborene Magier durch ein Portal hierher gebracht und um Unterstützung gebeten. Die Details sind verschwommen - eine Art getarnter Angriff auf die Stadt?\n\nIch weiß nicht, was ich davon halten soll, aber Jaina Prachtmeer ist bereits vor Ort und ich vermute, dass sie jede Hilfe brauchen werden.\n\nSprecht mit Seamus Goldtreter dort drüben, damit er Euch schnell nach Darnassus teleportiert. Findet Jaina!", sourceObjective = "Sprecht mit Seamus Goldtreter in der Löwenlandung, um Euch nach Darnassus transportieren zu lassen. Sprecht dort mit Jaina, sobald Ihr eingetroffen seid.", completion = "Die Glocke ist verschwunden...\n\nDort, wo sie gewesen war, finden sich Spuren arkaner Magie... Vielleicht kann ich die Diebe aufspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[32415] = { id = 32415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Spuren" }
quests[32416] = { id = 32416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jainas Entschluss", description = "Zu lange schon habe ich versucht, zwischen Allianz und Horde zu vermitteln. Immer und immer wieder habe ich der Horde vertraut, ihnen geglaubt – und immer und immer wieder haben sie dieses Vertrauen missbraucht.\n\nIch weigere mich, erneut verraten zu werden! Wenn die Horde die Kirin Tor als Waffe gegen die Allianz einsetzen will, dann hat sie in Dalaran nichts verloren.\n\nKommt mit, {name}.", sourceObjective = "Benutzt das Portal von Darnassus nach Dalaran und sprecht anschließend mit Vereesa Windläufer auf der anderen Seite.", completion = "Von jetzt an werde ich Euch instruieren.\n\nJaina wird sich in die Stadt begeben, um unsere neuen Regeln durchzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32417] = { id = 32417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung der Kanalisation", description = "Jaina leistet hervorragende Arbeit, die Sonnenhäscher hier auf der Oberfläche auszuschalten, aber es verbergen sich immer noch viele in der Kanalisation.\n\nFindet diese Ratten und macht ihnen den Garaus!", sourceObjective = "Tötet 12 Sonnenhäscher in der Kanalisation von Dalaran.", progress = "<Vereesa schaut auf ihre Stadt.>", completion = "Es ist schön, diese Ratten für immer von hier zu vertreiben. Gut gemacht, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[32418] = { id = 32418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungerechter Handel", description = "Die meisten Ladenbesitzer des Handelsmarktes der Magier haben sich auf die Seite des Silberbunds gestellt, doch einige wenige verweigern sich noch. Um sie müssen wir uns kümmern.\n\n<Vereesa zeigt Euch eine Liste mit Namen.>\n\nSie werden sich zur Wehr setzen.", sourceObjective = "Tötet Tintenmeister Aelon, Tolyria, Ausrüstungsmagier Astalon und Sintharia Funkenwirker.", completion = "Wenn ich auch nicht vollständig mit Jainas Methoden einverstanden bin, verstehe ich doch ihre Motive.\n\nManchmal muss man sich zur Wehr setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32419] = { id = 32419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Versteck", description = "Sonnenhäschers Zuflucht wimmelt immer noch von diesen Horde-liebenden Sonnenhäschern.\n\nDie Vernünftigen von ihnen wird Jaina bereits zur Violetten Festung gesandt haben. Die anderen weigern sich zu gehen und erheben ihre Waffen gegen uns.\n\nZeigt ihnen, was ihr Widerstand sie kosten wird. Jetzt werden die Allianz, der Silberbund und die Kirin Tor über sie richten!", sourceObjective = "Tötet 16 Sonnenhäscher in Sonnenhäschers Zuflucht.", completion = "Dies ist ein blutiger Tag, {name}, und es ist blutige Arbeit.\n\nAber vergesst nicht, womit die Sonnenhäscher dies verdient haben: Sie haben die Ressourcen der neutral eingestellten Kirin Tor genutzt, um der Horde im Kampf gegen die Allianz zu helfen.\n\nZweifelt nicht daran, dass sie genauso gegen uns vorgehen würden, wenn sie die Gelegenheit dazu hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32420] = { id = 32420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auszahlung", description = "Gerade habe ich gesehen, wie einer der Sonnenhäscher – Brasael heißt er, glaube ich – in Richtung der Bank im Norden gerannt ist. Ich bin mir sicher, dass er versucht, so viel Wertvolles wie nur möglich mitzunehmen.\n\nFangt ihn ab und stellt sicher, dass er uns nicht bestiehlt. Als er und die Sonnenhäscher uns verrieten, hat er jeglichen Anspruch auf sein Eigentum in der Bank verloren.", sourceObjective = "Tötet Magister Brasael.", completion = "Es war wohl nicht genug für ihn, ein Feigling und ein Verräter zu sein... er musste auch noch ein gieriger Dieb sein.\n\nHmph. Die Horde und die Sonnenhäscher passen eigentlich ganz gut zueinander.", sourceObjectiveStatus = "unverified-source-field" }
quests[32421] = { id = 32421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Ausweg", description = "Gefügige Sonnenhäscher werden zur Violetten Festung geschickt. Widerspenstige bekommen die Klinge zu spüren.\n\nKEINER darf entkommen.\n\nDie Sonnenhäscher haben ihre Drachenfalkenreittiere auf Krasus Landeplatz untergebracht. Nehmt diesen Staub und macht sie flugunfähig.\n\nOder bringt sie um. Mir soll beides Recht sein.", sourceObjective = "Macht 5 Drachenfalken der Sonnenhäscher flugunfähig.", completion = "Jetzt müssen sich die Sonnenhäscher unserer Gerechtigkeit stellen. Gefängnis oder Tod – die Wahl liegt in ihrer Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[32422] = { id = 32422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Violette Festung" }
quests[32423] = { id = 32423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was getan werden musste", description = "Vielen Dank, dass Ihr mir heute geholfen habt, {name}. Von hier an kümmere ich mich um die Säuberung.\n\nJaina wird bald zur Löwenlandung aufbrechen, um mit König Varian zu sprechen. Sie hat um Eure Anwesenheit gebeten.", sourceObjective = "Sprecht mit Vereesa Windläufer, um zur Löwenlandung zu reisen, und sprecht dann mit König Varian Wrynn.", completion = "Ich kann Euch nicht vorwerfen, dass Ihr Befehle befolgt habt. Und dieses Mal kann ich auch Jaina nicht vorwerfen, in ihrem eigenen Interesse gehandelt zu haben.\n\nUnd dennoch... dies ist kein Spiel. Hier geht es um Krieg, um Leben und Tod, gar um die Zukunft der Allianz.\n\nZumindest haben wir jetzt die Kirin Tor auf unserer Seite. Der heutige Tag wird als Sieg für die Allianz in die Geschichte eingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32424] = { id = 32424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was getan werden musste" }
quests[32425] = { id = 32425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Löwenlandung" }
quests[32426] = { id = 32426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerührt, nicht geschüttelt", description = "Also gut, ich werde Euch sagen, wie Ihr Connelly findet.\n\nAgent Connelly gibt sich derzeit als der Profiglücksspieler Professor Kilt aus. Er verbringt die meiste Zeit in Bizmos VIP-Lounge. Man sagt, dass er wegen eines längst vergessenen Verrats hinter einem der Kämpfer her ist.\n\nLeider wird man nur auf Einladung in diesen Raum eingelassen. Doch wie es der Zufall so will, habe ich eine solche.\n\nVersucht, nicht unnötig Aufmerksamkeit zu erregen, wenn Ihr die Türsteher passiert. Falls man Euch schnappt... diese Einladung kommt nicht von mir.\n\nWas mich betrifft, haben wir uns überhaupt nie getroffen!", sourceObjective = "Findet Professor Kilt in der VIP-Lounge von Bizmos Boxbar.", completion = "Der SI:7 muss wohl daran erinnert werden, was der Begriff \"Ruhestand\" bedeutet, was?\n\nIch schätze, sie würden sich nicht an mich wenden, wenn die Lage nicht verzweifelt wäre.\n\nIch werde helfen, aber ich brauche ein paar Tage, um die nötigen Informationen zu beschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32427] = { id = 32427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was den Anführer ausmacht", description = "Jetzt beginnt ein neuer Teil des Pandarenfeldzugs für uns. Euer Kriegshäuptling plant, die Pandaren mit der ganzen Macht des Heers der Horde zu beeindrucken. Er wird seinen Anspruch auf die Ressourcen dieses Landes erheben, sei es mit der Hilfe der Pandaren oder ohne sie.\n\nIch verstehe die Ziele Eures Anführers, aber ich möchte gern den Kriegshäuptling selbst verstehen. Was treibt ihn an? Und was will die Horde letztendlich wirklich erreichen? Ich würde mich gern mit Euch über Euren Anführer unterhalten.", sourceObjective = "Sprecht mit Furorion in der Taverne im Nebel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32428] = { id = 32428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandarischer Geisterzähmer", description = "Die Sagen erzählen von legendären Pandarengeistern, die Pandaria durchstreifen. Spürt sie auf und besiegt sie in einem Haustierkampf.", sourceObjective = "Besiegt sämtliche Pandarengeister in einem Haustierkampf.", completion = "Ich kann nicht fassen, dass Ihr diese Geister ausgeschaltet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[32429] = { id = 32429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinzliches Anliegen", description = "Mein Ziel ist ein schnelles Ende dieses kostspieligen Krieges. Beweist mir, dass die Horde den Sieg verdient. Demonstriert mir Euer Können auf dem Schlachtfeld.\n\nIhr habt es hier nicht mit einer abstrakten Macht wie dem Sha zu tun: Ihr steht Eurem Feind Angesicht zu Angesicht gegenüber.\n\nWerdet Ihr triumphieren?", sourceObjective = "Tötet Allianztruppen entlang der südlichen Küsten der Krasarangwildnis bis Ihr beim Schwarzen Prinz einen respektvollen Status erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32430] = { id = 32430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führungswechsel", description = "Es gibt da einen Zwerg der Allianz, den ich beobachtet habe. Hochmarschall Doppelzopf hat sich im Südlichen Brachland als Ärgernis erwiesen, als er sich nach dem Verlust von Bael Modan gegen die Horde zur Wehr setzte. Jetzt hat er sich in der Festung der Allianz in der Löwenlandung verschanzt und hilft dabei, die Krasaranggegenoffensive zu orchestrieren.\n\nNur eine Gruppe legendärer Helden der Horde kann ihn besiegen.\n\nWenn Ihr ihn aus dem Weg schaffen wollt, bringt Freunde mit. Jede Menge Freunde.", sourceObjective = "Tötet Hochmarschall Doppelzopf in der Löwenlandung in der Krasarangwildnis. Ihr werdet dafür eine Gruppe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32431] = { id = 32431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm der Horde", description = "Dies ist ein weltweiter Krieg, {name}. Er ist bis nach Pandaria gelangt und hat Krisenherde in Kalimdor und den Östlichen Königreichen in Brand gesetzt. Wie verhaltet Ihr Euch in einem organisierten Kampf? Das würde ich gern selbst sehen.\n\nIch erwarte Euren Bericht von der Front.", sourceObjective = "Gewinnt Kämpfe beim Tempel von Katmogu und in der Silberbruchmine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32432] = { id = 32432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seele der Horde", description = "{class}, durch Eure Augen wurde ich Zeuge der Kämpfe an der Küste und der epischen Schlachten überall auf der Welt. Ihr habt Euch als sehr geduldig... und äußerst informativ erwiesen.\n\nAuch Garrosh Höllschrei habe ich fest im Auge behalten. Würdet Ihr gerne hören, was ich dabei erfahren habe?", sourceObjective = "Sprecht mit Furorion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32433] = { id = 32433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Mine unten unterminieren", description = "Grezik Erzschleif hat sich zu einem Ärgernis entwickelt, das es zu eliminieren gilt.\n\nWie Ihr sicher wisst, reagiert dieses Land auf all unsere Taten, {class}. Aus diesem Grunde können wir nicht zulassen, dass diese Goblins es so mir nichts, dir nichts zerstören.\n\nUnsere Späher haben berichtet, wie Sha aus Erzschleifs Grabung dringt. Der Drahtzieher hinter der Operation ist ein gewisser Goblin namens Grezik Erzschleif.\n\nBesiegt ihn und vielleicht können wir den Betrieb lang genug lahmlegen, um das Sha einzudämmen.", sourceObjective = "Vernichtet Grezik Erzschleif bei Erzschleifs Grabung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32434] = { id = 32434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den brennenden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32435] = { id = 32435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiter Platz", progress = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr Zweiter werden wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!" }
quests[32436] = { id = 32436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritter Platz" }
quests[32437] = { id = 32437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Sarannha gesehen 2" }
quests[32438] = { id = 32438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Sarannha gesehen 1" }
quests[32439] = { id = 32439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fließender Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den fließenden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32440] = { id = 32440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüsternder Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den flüsternden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32441] = { id = 32441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bebender Pandarengeist", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", sourceObjective = "Besiegt den bebenden Pandarengeist in einem Haustierkampf.", completion = "Nächstes Mal werde ich Euch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32442] = { id = 32442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohende Gefahr", description = "Unsere Späher haben ein Teufelskommandoschiff am Horizont entdeckt, <Großmeister/Großmeisterin>. Offenbar ist es auf Kollisionskurs mit der Wandernden Insel.\n\nWir sollten unsere Truppen auf das Schlimmste vorbereiten – einen Großangriff.\n\nBis dahin sollten wir unsere Champions vorschicken, damit sie versuchen, die Aufmerksamkeit des Legionsschiffs abzulenken.", sourceObjective = "Schließt die Mission \"Drohende Gefahr\" ab.", completion = "Unsere Champions haben die erste Welle Angreifer besiegt, aber das Kommandoschiff hat uns beinahe erreicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[32444] = { id = 32444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Earned Brawler Title (Weekly)" }
quests[32446] = { id = 32446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte auseinandernehmen", description = "Die Schredder werden dort unten zu einem Problem, {class}.\n\nWir haben die Mecha-Stampfer geschickt, aber das reicht leider nicht aus. Sie werden schneller beschädigt, als wir sie reparieren können!\n\nIch habe zufällig während einer Aufklärungsmission diese seltsame Fernbedienung gefunden. Ich glaube, wir können sie gebrauchen, wenn die Einstellungen ein wenig geändert werden.\n\nSetzt sie versuchsweise gegen die Dschungelschredder ein. Hoffentlich können sie damit zerstört werden. Wenn ja, bringt mir bitte das Altmetall mit.", sourceObjective = "Zerstört mit der rekonfigurierten Fernsteuerung die Dschungelschredder und sammelt dann 6 Stücke Metallschrott.", progress = "Wie genau funktioniert die Fernsteuerung?", completion = "Von Goblins konstruierte Geräte lassen zu Wünschen übrig, aber es muss ausreichen. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32448] = { id = 32448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Vergangenheit verbunden", description = "Als ich im Tal war, bin ich auf ein uraltes Pandarenrezept für Wein der Erinnerungen gestoßen. Ich glaube, dieses Gebräu könnte einige hilfreiche Informationen aus Shan Kien hervorlocken.\n\nIch werde hier gebraucht, also bleibt mir keine andere Wahl als Euch zu bitten, die grundlegende Zutat für mich zu besorgen. Wir brauchen die Geistessenz eines Mogu, der zur Zeit der Erinnerung, die wir sehen wollen, gelebt hat.\n\nGenau einen solchen Geist solltet Ihr auf dem Pfad der Eroberer nordöstlich von hier zu finden vermögen.", sourceObjective = "Besorgt die Geistessenz von Varatus.", progress = "Man weiß nie, was man in einem Buch finden wird. Erst recht nicht in einem uralten pandarischen Buch.\n\nIch möchte gern sehen, wie dieser Wein der Erinnerungen funktioniert.", completion = "Ah, sehr gut. Das ist die letzte erforderliche Zutat.", sourceObjectiveStatus = "unverified-source-field" }
quests[32449] = { id = 32449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Ogudei", description = "Unsere Späher am Außenposten Zündmine haben neue Aktivitäten in der Nähe eines Gebiets gemeldet, das die Ruinen von Ogudei genannt wird.\n\nWir müssen Informationen darüber sammeln, was die Allianz tut und - wichtiger noch - was sie gefunden hat. Wir können uns keine unbekannten Faktoren leisten.\n\nTrefft Euch mit Bellok Leuchtklinge im Außenposten Zündmine und findet heraus, was er weiß.", sourceObjective = "Meldet Euch bei Bellok Leuchtklinge im Außenposten Zündmine.", completion = "Wir haben viel zu tun, {class}. Wer weiß, was in Ogudei bereits zum Vorschein gekommen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[32450] = { id = 32450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt oder nie!", description = "Jetzt greifen wir sie an, {class}!\n\nMeldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine. Sie wird Euch Eure Befehle erteilen.\n\nJetzt wird sich zeigen, wie sie damit umgehen, wenn die Horde mit ganzer Macht ihre kostbare Festung stürmt!", sourceObjective = "Meldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine.", completion = "Jetzt können die Dinge spannend werden! Ich habe einige Pläne für die Löwenlandung...", sourceObjectiveStatus = "unverified-source-field" }
quests[32451] = { id = 32451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Nachricht senden", description = "Zeit, dass wir diesen Mistkerlen von der Horde die ganze Stärke der Allianz zeigen! Heute bringen wir den Kampf an ihre Tore.\n\nMeldet Euch bei Admiralin Rogers an Bord der Himmelsfeuer. Sie wird Euch weitere Anweisungen erteilen.\n\nViel Glück da draußen, {class}. Macht der Allianz Ehre!", sourceObjective = "Meldet Euch bei Himmelsadmiralin Rogers an Bord der Himmelsfeuer in der Krasarangwildnis.", completion = "Die Schlacht hat bereits begonnen, {class}. Begeben wir uns hinaus!", sourceObjectiveStatus = "unverified-source-field" }
quests[32452] = { id = 32452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und dann gab's Goblins", description = "Wir führen Krieg an allen Fronten, {class}. Sogar Pandaria selbst braucht unseren Schutz.\n\nDie Bilgewässer Goblins zerstören Land, das nicht ihnen gehört. Sie müssen aufgehalten werden!\n\nMeldet Euch bei Himmelsadmiralin Rogers auf der Himmelsfeuer. Ihr Aussichtspunkt sollte ihr einen besseren Überblick darüber verschaffen, wo die Schwachstellen sind.", sourceObjective = "Meldet Euch bei Himmelsadmiralin Rogers an Bord der Himmelsfeuer in der Krasarangwildnis.", completion = "War auch Zeit, dass wir uns um dieses Ärgernis gekümmert haben. Jemand muss diesen Bilgewässer Kümmerlingen eine Lektion erteilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32455] = { id = 32455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stille", description = "H… haben wir... es geschafft?\n\n<Anduin murmelt die Worte, obwohl es ihn sichtlich anstrengt.>\n\nS… seht... in... meiner... Tasche nach...\n\nBenutzt das... Leuchtfeuer...", sourceObjective = "Benutzt die Leuchtpistole der Allianz.", completion = "Ich mag gar nicht daran denken, was passiert wäre, wärt Ihr nicht bei dem jungen Prinzen gewesen, {name}.\n\nHeute habt Ihr Garroshs Pläne durchkreuzt.\n\nIhr habt zweifellos Tausende Leben gerettet und zudem Anduin zu uns zurückgebracht.\n\nWir tun für den Jungen, was wir können, jetzt müssen wir aber geduldig sein.\n\nIch glaube, er wird durchkommen. Ich muss daran glauben...", sourceObjectiveStatus = "unverified-source-field" }
quests[32457] = { id = 32457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Donnerkönig", description = "Wisst Ihr, was sich am Kun-Lai-Gipfel ereignet hat? Die Zandalari sind in Scharen an der Nordküste gelandet und haben mit dem Erneuern alter Bündnisse begonnen. Zu diesem Zweck haben sie den Donnerkönig wiederbelebt.\n\nSelbst bei den Mogu ruft der Name des ersten Herrschers Angst und Schrecken hervor. Der Donnerkönig errichtete ein riesiges Reich der Sklaverei und des Leidens... doch auch der Macht, des Reichtums und der Pracht.\n\nWir werden ihm bald im Kampf gegenüberstehen. Kommt zu mir, wenn Eure Fraktion ihren nächsten Zug macht.", sourceObjective = "Kontaktiert Furorion im zweiten Stock der Taverne im Nebel an der Verhüllten Treppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32458] = { id = 32458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Segen des Windes...", description = "<Eine dringende Bitte kommt Euch zu Ohren.>\n\n{name}! Die Flotte meines Vaters ist nach Pandaria unterwegs. Bei gutem Wind könnte sie jeden Augenblick eintreffen.\n\nDie Pandaren haben einen Segen, der uns Glück mit dem Wetter gewähren und die Reise unserer Schiffe zu diesen Gefilden beschleunigen wird. Damit uns das Glück hold ist, müssen wir nichts weiter als Amulette des Glücks sammeln.\n\nJe näher unsere Schiffe der Insel kommen, umso weniger Amulette werden nötig sein. Doch wenn Ihr genug davon habt, können wir sie direkt hierher bringen...", sourceObjective = "Sammelt Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32459] = { id = 32459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Segen des Windes...", description = "<Eine dringende Bitte kommt Euch zu Ohren.>\n\n{name}! Die Flotte der Horde ist nach Pandaria unterwegs. Bei gutem Wind könnte sie jeden Augenblick landen.\n\nDie Pandaren haben einen Segen, der uns Glück mit dem Wetter gewähren und die Reise unserer Brüder und Schwestern zu diesen Gefilden beschleunigen wird. Damit uns das Glück hold ist, müssen wir nichts weiter als Amulette des Glücks sammeln.\n\nJe näher unsere Schiffe der Insel kommen, umso weniger Amulette werden nötig sein. Doch wenn Ihr genug davon habt, können wir sie direkt hierher bringen...", sourceObjective = "Sammelt Amulette des Glücks.", sourceObjectiveStatus = "unverified-source-field" }
quests[32460] = { id = 32460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Dieben auf der Spur", description = "Wir WERDEN der Sache auf den Grund gehen.\n\n{name}, Ihr kommt mit. Wenn es sein muss, werden wir jeden Winkel dieser Stadt durchsuchen. Und wir werden herausfinden, wie sie die Glocke mitgenommen haben... und wo sie ist.\n\nIch erfasse hier Spuren arkaner Magie... folgen wir der Spur!", sourceObjective = "Helft Jaina dabei, herauszufinden, wer die Götterglocke gestohlen hat und wo sie hingebracht wurde. Ihr könnt Euch von Seamus Goldtreter in der Löwenlandung nach Darnassus teleportieren lassen.", completion = "Ich habe entschieden.\n\nGewissen Angehörigen der Kirin Tor ist ihre Loyalität gegenüber der Horde wichtiger als der Orden. Das werde ich NICHT zulassen.\n\n<Jainas Augen glühen vor Wut auf.>\n\nKommt mit, {name}. Wir werden in Dalaran aufräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32461] = { id = 32461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orden der Wolkenschlange", description = "Ahhh, Ihr seid jetzt also <stolzer Besitzer/stolze Besitzerin> einer majestätischen Wolkenschlange.\n\nEhe Ihr Euch auf dem Rücken dieser mächtigen Kreatur in die Lüfte erheben könnt, müsst Ihr die Fertigkeit sie zu reiten erwerben.\n\nDer Orden der Wolkenschlange kann Euch das gewünschte Wissen lehren.\n\nWenn Ihr unserem Weg zu folgen wünscht, sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.\n\nIch wünsche Euch Glück, {race}.", sourceObjective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[32467] = { id = 32467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfer verhindern", description = "Die Priester der Zandalari in der Stadt nördlich von hier bereiten die Leichname unserer gefallenen Verbündeten zur Opferung vor.\n\nWie man das am besten verhindern kann? Tötet sie. Tötet sie alle.", sourceObjective = "Tötet 5 Priester der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32468] = { id = 32468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklar", description = "Also, es gibt da eine Möglichkeit, wie man Eure S.E.L.F.I.E.-Kamera verbessern kann, wenn Euch das interessiert. Mit der richtigen Fokussierlinse könnte ich das Ding mit allen möglichen Funktionen ausstatten.\n\nIch habe gehört, dass die Mutter aller Basilisken draußen auf der Insel Yojamba im Schlingendorntal gesehen worden sei. Ihre Haut ist mit Edelsteinen überzogen. Wenn ich die bekäme, könnte ich die perfekte Linse daraus machen.\n\nSie ist aber alles andere als leichte Beute. Ihr solltet vielleicht ein paar Freunde mitnehmen.", sourceObjective = "Sammelt 1 makellosen Kristallsplitter von der Kristallrückenmatriarchin auf der Insel Yojamba im Schlingendorntal.", progress = "Die Kristallrückenmatriarchin hat die Edelsteine, die wir zum Verbessern Eurer Linse brauchen. Konntet Ihr sie besorgen?", completion = "Ich muss sagen, ich bin schon überrascht, Euch wiederzusehen. Ihr seid anscheinend zäher, als ich dachte. Ihr habt meinen Respekt verdient, hier ist also Euer Profi-Objektiv. Und jetzt los und macht ein paar S.E.L.F.I.E.S!", sourceObjectiveStatus = "unverified-source-field" }
quests[32469] = { id = 32469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklar", description = "Hallo noch mal! Oh, ich hab vergessen, Euch etwas zu erzählen! Ich habe eine todsichere Methode entwickelt, Eure S.E.L.F.I.E.-Kamera zu verbessern! \n\nUnd zwar kann ich mithilfe der richtigen Edelsteine eine Linse herstellen, mit der man alles Mögliche anstellen kann!\n\nEin paar Forscherkollegen haben mir von einem großen Basilisken auf der Insel Yojamba im Schlingendorntal berichtet. Die Haut ist mit jeder Menge qualitativ hochwertiger Edelsteine überzogen! Das ist einfach perfekt!\n\nAber es scheint ein zähes Biest zu sein! Nehmt besser ein paar Freunde mit!", sourceObjective = "Sammelt 1 makellosen Kristallsplitter von der Kristallrückenmatriarchin auf der Insel Yojamba im Schlingendorntal.", progress = "Hey, raus aus meiner Schusslinie! Oh, Ihr seid es! Habt Ihr schon den Basilisken erlegt?", completion = "Ich wusste sofort, als wir uns kennengelernt haben, dass Ihr zu der Klasse Abenteurer zählt, auf die man sich verlassen kann! Hier ist Euer Profi-Objektiv. Und jetzt los, macht ein paar S.E.L.F.I.E.S!", sourceObjectiveStatus = "unverified-source-field" }
quests[32470] = { id = 32470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht, Kamera uuund Action!", description = "Oh, hallo! Ist das nicht ein tolles Foto? Ich liebe meine S.E.L.F.I.E.-Kamera!\n\nSoll ich Euch auch eine bauen? Ich brauche dafür nur ein paar Teile!\n\nFür den Gurt brauche ich einen rotbraunen Gürtel von einem der Rüstungshändler in Sturmwind.\n\nIch hab auch schon ein paar Gehäuse bestellt. Ihr könnt eines davon haben, wenn Ihr herausfinden könnt, wo meine Lieferung abgeblieben ist!\n\nOh, und ein Standardzielfernrohr sollte Euch eigentlich jeder Ingenieur herstellen können.\n\nAlso, seid Ihr bereit für einen Ausflug in die Welt der Fotografie?", sourceObjective = "Beschafft Euch eine eiserne Kiste und einen rotbraunen Gürtel in der Hauptstadt und ein Standardzielfernrohr von einem Ingenieur.", progress = "Wollt Ihr das Bild mal sehen? Ich könnte den ganzen Tag hier Bilder machen! Habt Ihr die Teile bekommen?", completion = "Sehr gut! Nur noch ein bisschen an der Kiste arbeiten und dieses Teil da reinbauen und... fertig!\n\nHier ist Eure neue S.E.L.F.I.E.-Kamera. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[32471] = { id = 32471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht, Kamera uuund Action!", description = "Ihr seht aus, als hättet Ihr ein Talent für die visuellen Künste. Wollt Ihr Euch vielleicht mal an der Fotografie versuchen?\n\nIch kann Euch so eine S.E.L.F.I.E.-Kamera bauen. Ich brauche dafür nur ein paar Teile.\n\nFür den Gurt brauche ich einen rotbraunen Gürtel von einem der Rüstungshändler in der Gegend.\n\nUnd am Eingang der Stadt wartet eine Lieferung Gehäuse auf mich. Nehmt Euch eines davon, wenn Ihr da seid.\n\nOh, und ein Standardzielfernrohr sollte Euch eigentlich jeder Ingenieur herstellen können.\n\nUnd jetzt raus mit Euch, denn der Ruhm wartet!", sourceObjective = "Beschafft Euch eine eiserne Kiste und einen rotbraunen Gürtel in der Hauptstadt und ein Standardzielfernrohr von einem Ingenieur.", progress = "Habt Ihr die Teile, oder nicht? Ich bin nämlich sehr beschäftigt!", completion = "Es kann losgehen. Ihr habt das perfekte Gesicht für die Kamera. Und jetzt auf zum fröhlichen Fotografieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[32472] = { id = 32472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterodaktylen erschrecken", description = "Die Pterodaktylusjungtiere, die die Zandalari im Norden ausbilden, sind noch nicht die brutalen und wilden Bestien, die sie einst werden sollen.\n\nIch finde, wir sollten diese Kreaturen retten, bevor die Trolle sie verderben. Wenn Ihr sie einfach verscheuchen könnten, bleibt ihnen vielleicht ein unglückseliges Schicksal erspart.", sourceObjective = "Erschreckt 12 Pterodaktylusjungtiere.", sourceObjectiveStatus = "unverified-source-field" }
quests[32474] = { id = 32474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapferkeitsbeweis", description = "<Ohne Vorwarnung schneidet sich Furorion in den Daumen und drückt ihn an Eure Stirn. Sein Blut brennt bei der Berührung, verschwindet jedoch schnell in Eurer Haut.>\n\nSo! Mein Auge wacht nun über Euch, {class}. Ich beobachte Euch.\n\nDie Pandaren wissen das Konzept der \"Tapferkeit\" genauso zu schätzen wie die Allianz. Auf diesem Kontinent gibt es viele Möglichkeiten, Euch würdig zu erweisen - von alltäglichen Aufgaben bis hin zum Bezwingen heroischer Gegner in ihrem Versteck. Ich überlasse es Euch, Euren eigenen Weg zu wählen.\n\nBeweist mir Euren Mut, {name}!", sourceObjective = "Erlangt den Erfolg \"Tapferkeitsbeweis\", indem Ihr insgesamt 3000 Tapferkeitspunkte verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[32475] = { id = 32475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Lebensfunke", description = "Das donnerversetzte Ei verbrennt Euch die Hand, während Ihr es haltet. Ihr erinnert Euch vage, dass Yalia Weisenwisper von den Shado-Pan über die Geschichte der donnernden Wolkenschlangen gesprochen hat. Vielleicht wird sie wissen, was hiermit anzufangen ist.", sourceObjective = "Bringt das donnerversetzte Ei zu Yalia Weisenwisper auf der Insel des Donners.", sourceObjectiveStatus = "unverified-source-field" }
quests[32476] = { id = 32476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Valor" }
quests[32477] = { id = 32477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Player is Back in Time" }
quests[32485] = { id = 32485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung stärken", description = "Diese Insel ist ein gefährlicher Ort, {name}. Wir müssen uns über Angriffe der Zandalari, Mogu, Saurok und – und das ist am schlimmsten – Angriffe der Sonnenhäscher Gedanken machen.\n\nIch habe Schutzzauber um die Grenzen unseres Lagers herum aufstellen lassen. In ihrem momentanen Zustand verletzen sie Angreifer nur leicht, aber ich habe genug von Warnungen!\n\nMit Eurer Hilfe können wir die Schutzzauber überladen und zu einem tödlicheren Verteidigungssystem machen.", sourceObjective = "Ladet 6 Schutzzauber der Kirin Tor auf der Violetten Erhebung auf.", completion = "Exzellente Arbeit, {name}. Diese Schutzzauber sollten alles Mögliche an Abschaum fernhalten.\n\nJetzt, da die Violette Erhebung geschützt ist, können wir uns um dringendere Angelegenheiten kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[32489] = { id = 32489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die krabbelnde Decke auf Ihgaluk", description = "Ach ja, Schaben! Ich habe in Unterstadt mal eine Schabe als Haustier gekauft.\n\nSchaben saugen Krankheiten auf wie kleine Schwämme, und dann verbreiten sie sie, so schnell sie nur laufen können. Und sie können ziemlich weit laufen.\n\nDie Ihgalukklamm wimmelt von den Dingern, und sie verteilen den Dreck der Skumklingen über die ganze Insel. Zerquetscht so viele von ihnen wie Ihr nur könnt, während Ihr dort seid.", sourceObjective = "Zerquetscht 75 Ihgaluk-Schaben.", completion = "Jedes bisschen hilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[32490] = { id = 32490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "UNBENUTZT" }
quests[32491] = { id = 32491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrotten lassen", description = "Die Saurok der Skumklingen verzehren nicht alles Fleisch, das sie erjagen. Sie behalten große Teile davon zurück, die in Stapeln neben ihren Behausungen verrotten und so Ungeziefer anziehen und Krankheiten ausbreiten.\n\nWir können nicht zulassen, dass die Saurok ihre Krankheiten außerhalb der Ihgalukklamm verbreiten. Beseitigt alles überschüssige Fleisch, das Ihr finden könnt.", sourceObjective = "Zerstört 3 faulige Fleischhaufen.", completion = "Würden sie stehen bleiben, wären diese Haufen weggeworfener Fleischreste eine perfekte Brutstätte für Krankheiten.\n\nWäre ich noch im Sektor der Krankheitsverbreitung tätig, würde ich in Betracht ziehen, sie selbst zu benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32492] = { id = 32492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kessel zerstören" }
quests[32493] = { id = 32493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Ende sterben alle", description = "Die Zandalari dulden keine Schwäche in ihren Reihen, {class}.\n\nJene, die für schwach befunden werden, werden oft in barbarischen Zeremonien geopfert. Ihre Geister werden gefangen und in die Wachen eingeschlossen, die Ihr dieses Gelände hier behüten seht.\n\nIch möchte mich dem Studium ihrer Essenz widmen. Dafür werde ich Eure Hilfe benötigen.\n\nNehmt diesen Resonanzkristall und entzieht die Geister den Überresten der Wächter.\n\nLasst sie nicht entkommen!", sourceObjective = "Zerstört 5 geist-gebundene Wachposten und nutzt den Resonanzkristall, um die in ihnen gefangenen Zandalarigeister einzusammeln.", completion = "Exzellente Arbeit, {class}! Das wird sowohl meine Studien als auch unsere Kampagne hier ein großes Stück vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32494] = { id = 32494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtspiele", description = "Die Zandalari haben einen Weg gefunden, machtvolle Artefakte mit der Essenz ihrer Loa zu erfüllen. Diese Gegenstände werden oft von einer Generation an die nächste weitergereicht, wobei jeder Empfänger etwas zu ihrer Macht beiträgt.\n\nZwei solcher Gegenstände gibt es hier. Zwei Masken genauer gesagt, die von zwei Brüdern getragen werden.\n\nGeisterbinder Tu'chek und Arkanital Ra'kul müssen aufgehalten und ihre Masken zerstört werden.\n\nTötet die beiden und bringt die Artefakte zu mir. Ich werde dafür sorgen, dass sie vernichtet werden.", sourceObjective = "Entwendet Geisterbinder Tu'chek und Arkanital Ra'kul auf der Terrasse des Eroberers die Maske des dunklen Mystikers und die Maske des Geisterrufers.", progress = "Habt Ihr die Masken?", completion = "Diese Masken zu beschaffen war keine leichte Aufgabe, {class}. Ich bin für Euren Dienst dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[32495] = { id = 32495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutvergießer", description = "Mir ist ein verstörender Bericht zu Ohren gekommen, {class}.\n\nGanz in der Nähe, im Hof der Knochen, bringen die Mogu ihre Gefangenen zu einem General namens \"Kaida der Blutvergießer\".\n\nIch erspare Euch die Details, aber er lebt dafür, seine Opfer zu foltern.\n\nDieses Monster muss aufgehalten werden. Solltet Ihr seiner Klinge zum Opfer fallen, wünsche ich Euch einen raschen Tod.", sourceObjective = "Tötet Kaida den Blutvergießer.", progress = "Die Mogu sind zu unvorstellbaren Grausamkeiten fähig.", completion = "Ich freue mich zu hören, dass dieser Mistkerl tot ist. Ihr habt uns allen einen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32496] = { id = 32496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Horde im Tal der Ewigen Blüten!", sourceObjectiveStatus = "unverified-source-field" }
quests[32497] = { id = 32497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in der Schreckensöde.", completion = "Ehrt die Flamme der Schreckensöde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32498] = { id = 32498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer im Jadewald.", completion = "Ehrt die Flamme des Jadewalds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32499] = { id = 32499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in der Krasarangwildnis.", completion = "Ehrt die Flamme der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32500] = { id = 32500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer am Kun-Lai-Gipfel.", completion = "Ehrt die Flamme des Kun-Lai-Gipfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[32501] = { id = 32501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in der Tonlongsteppe.", completion = "Ehrt die Flamme der Tonlongsteppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32502] = { id = 32502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer im Tal der Vier Winde.", completion = "Ehrt die Flamme des Tals der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32503] = { id = 32503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz im Tal der Ewigen Blüten!", sourceObjectiveStatus = "unverified-source-field" }
quests[32504] = { id = 32504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Geheimnisse von Sturmwind", description = "Schickt Truppen in verdeckter Mission in das Herz des feindlichen Gebietes, um ihre Pläne zu erfahren." }
quests[32505] = { id = 32505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zerfallene Kämmerer", description = "Ihr dort! Helft mir.\n\nAls ich noch lebte, war ich der Kämmerer Seiner Majestät des Donnerkönigs. Für meine Ergebenheit wurde ich zu dieser steinernen Form verdammt, dazu bestimmt, auf ewig einen Teil seiner Schätze zu bewachen.\n\nDoch jemand hat meinen prachtvollen Körper entweiht und seine Teile über die Insel verteilt. Der Gedanke, die Ewigkeit als nichts weiter als ein Kopf zu verbringen, bedrückt mich.\n\nSucht die Insel ab, bringt meine Teile zurück und ich werde Euch einen der Schätze Seiner Majestät gewähren.", sourceObjective = "Findet die Schulter, den Kopf, den Stab, das Haar und den Torso des Kämmerers.", progress = "Ich benötige ALLE meine Teile. Sollte auch nur ein einziger Kiesel fehlen, werde ich es in Betracht ziehen unsere Abmachung als hinfällig zu werten.", completion = "Ah! Sich endlich wieder als Ganzes zu fühlen! Ihr habt meinen Dank, Diener. Nehmt diesen Stein und setzt ihn weise ein. Solltet Ihr auf Euren Reisen Seiner Majestät dem Donnerkönig begegnen, so sagt ihm nicht, wo Ihr diesen Stein erhalten habt - sonst werdet Ihr Euch als Statue an meiner Seite wiederfinden. Für alle Ewigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32506] = { id = 32506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrorschwingen verleihen Flügel", description = "Ich habe gerade den Bericht erhalten, dass eine weitere junge Pterrorschwinge im Düstermoor gesehen wurde.\n\nWir müssen so viele von ihnen einfangen, wie wir nur können. Sie sind vielleicht der Schlüssel zum Fliegen auf dieser Insel.", sourceObjective = "Fangt ein wildes Pterrorschwingenjungtier.", sourceObjectiveStatus = "unverified-source-field" }
quests[32507] = { id = 32507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Haut eines Saurok", description = "Die Ihgalukklamm ist ein gefährlicher Ort. Glücklicherweise stärkt Euch die Magie der Sonnenhäscher den Rücken.\n\nIch kann Euch in einen Saurok verwandeln.\n\nIch werde jetzt die erste Hälfte der Illusion auf Euch wirken. Danach solltet Ihr sofort zur Ihgalukklamm gehen und einen Skumklingensaurok töten. Sobald Ihr das erledigt habt, werde ich Euch kontaktieren und die zweite Hälfte vollenden.", sourceObjective = "Begebt Euch zur Ihgalukklamm und tötet einen Skumklingensaurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32508] = { id = 32508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen auf der Insel" }
quests[32509] = { id = 32509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme des Tals der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32510] = { id = 32510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme des Tals der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32516] = { id = 32516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutvergießer", description = "Mir ist ein verstörender Bericht zu Ohren gekommen, {class}.\n\nIm Süden, im Hof der Knochen, bringen die Mogu ihre Gefangenen zu einem General namens \"Kaida der Blutvergießer\".\n\nIch erspare Euch die Details, aber er lebt dafür, seine Opfer zu foltern.\n\nDieses Monster muss aufgehalten werden. Solltet Ihr seiner Klinge zum Opfer fallen, wünsche ich Euch einen raschen Tod.", sourceObjective = "Tötet Kaida den Blutvergießer.", sourceObjectiveStatus = "unverified-source-field" }
quests[32517] = { id = 32517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die steinerne Eroberung", description = "Im Hof der Knochen führen die Zauberer des Donnerkönigs finstere Rituale durch.\n\nUm ihre Truppen zu verstärken, hauchen die Seelenreißer der Shan'ze uralten Steinstatuen die Geister der Lebenden ein.\n\nSind diese Steineroberer einmal zum Leben erweckt, werden sie furchterregende Gegner auf dem Schlachtfeld sein.\n\nWir müssen ihr Ritual unterbrechen, bevor diese Statuen erweckt werden können.", sourceObjective = "Unterbrecht das Ritual des uralten Steineroberers im Haupttempel im Hof der Knochen.", completion = "Eine gute Verteidigung ist genauso effektiv wie eine starke Offensive. Ein Feind weniger, um den wir uns Gedanken machen müssen.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32518] = { id = 32518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[32519] = { id = 32519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[32520] = { id = 32520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konkurrierende Magie", description = "Meine Späher haben diesseits von Za'Tual einen gefährlichen Zandalari entdeckt. Ich brauche jemand Fähigen, der dafür sorgt, dass er beseitigt wird. Traut Ihr Euch das zu?", sourceObjective = "Tötet Arkanwirker Jor'guva.", completion = "Eure Fähigkeiten sind in der Tat beeindruckend. Danke, dass Ihr das für mich getan habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32521] = { id = 32521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindlicher Übergriff", description = "Meine Späher haben an der Nordküste einen Kriegstrupp der Zandalari entdeckt. Ich brauche jemand Fähigen, der dafür sorgt, dass er beseitigt wird. Traut Ihr Euch das zu?", sourceObjective = "Tötet Nurkala, den Kriegsanführer der Zandalari.", completion = "Ihr habt unseren Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32522] = { id = 32522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposante Bedrohung", description = "Meine Späher haben unterhalb des zentralen Turms einen Anführer der Mogu entdeckt. Er muss sterben, bevor er einen Angriff gegen unsere Stellung anzettelt.\n\nKönnt Ihr Euch für mich darum kümmern?", sourceObjective = "Tötet Horgak den Versklaver.", progress = "Ist es getan?", completion = "Eine Bedrohung weniger an unserer Türschwelle. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32523] = { id = 32523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bestienpferche", description = "Wir müssen diesen Bestien, die die Zandalari gegen unser Lager auffahren, irgendetwas entgegensetzen. Ich habe Späherhauptmann Elsia zu den Bestienpferchen geschickt; zusammen mit einigen Kriegsmagiern, die für Deckung sorgen.\n\nGeht nach Osten und sucht sie in der Nähe des Mauerdurchbruchs. Helft ihr, die Zahl der Reiterei und Belagerungseinheiten einzuschränken, die gegen uns aufgebracht werden können.\n\nSie sind durch Magie getarnt, haltet also Ausschau nach dem Schimmer ihrer Tarnzauber.", sourceObjective = "Findet Späherhauptmann Elsia in den Bestienpferchen.", completion = "Ich bin froh, dass Lor'themar Euch gesandt hat. Diese Bestien sind mehr, als wir allein handhaben können. Jetzt wird es Zeit, das Vieh zu verscheuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32524] = { id = 32524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Takt der Trolltrommeln", description = "Hört Ihr das, {class}? Den Klang von Kriegstrommeln in der Ferne. Die Zandalari bereiten sich auf uns vor.\n\nWir werden ihnen nicht den Luxus gewähren, ihre Verteidigungslinie zu organisieren. Unser Angriff muss jetzt stattfinden!\n\nMeldet Euch bei Späherhauptmann Elsia auf der Terrasse des Eroberers. Sie hält weitere Befehle für Euch bereit.", sourceObjective = "Sucht Späherhauptmann Elsia auf der Terrasse des Eroberers.", completion = "Die Zandalari sind sogar noch gefährlicher, als wir angenommen haben.\n\nMacht niemals den Fehler sie zu unterschätzen. Es könnte der letzte sein, den Ihr begeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32525] = { id = 32525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche des Feindes", description = "Die Mogu im Hof der Knochen stocken ihre Armee auf, indem sie die Geister ihrer Gefallenen erwecken.\n\nWir dürfen nicht zulassen, dass sie ihre gefallenen Krieger wiederbeleben.\n\nNehmt diese Fackel und verbrennt alle mumifizierten Leichen, die Ihr finden könnt.\n\nWir werden unsere Feinde vernichten, bevor sie die Gelegenheit haben, aufzuerstehen.", sourceObjective = "Verbrennt 8 mumifizierte Überreste.", completion = "Dank Euch werden die Toten nicht mehr auferstehen, {name}. Exzellente Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32526] = { id = 32526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenrettung", description = "Wir bekämpfen die Mogu im Hof der Knochen, aber ich fürchte, dass wir ihnen nur Material für ihre abscheulichen Rituale liefern.\n\nDie Mogu töten ihre Gefangenen nicht einfach – sie stehlen ihre Seelen und hauchen sie Gerätschaften aus Stein ein oder formen die Gefallenen zu geisterhaften Kriegsmaschinen um.\n\nHorde oder Allianz, es macht keinen Unterschied. Wir können den Mogu nicht erlauben ihre Reihen wieder aufzustocken.\n\nGeht zur Grabstätte. Befreit die Gefangenen, die noch leben.", sourceObjective = "Rettet 6 Späher des Silberbunds oder der Sonnenhäscher.", completion = "Danke, {name}. Ihr habt mein Herz durch Eure heldenhaften Taten von einer schweren Last befreit. \n\nIch werde Eure heutigen Anstrengungen in Erinnerung behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32527] = { id = 32527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gravierende Umstände", description = "Der Hof der Knochen wimmelt von Truppen der Mogu. Ohne Unterlass führen sie ihre Rituale von Blitz und Donner aus.\n\nWenn wir unseren Auftrag, diese Insel zu erobern, erfüllen sollen, dürfen wir nicht zulassen, dass sie eine so wichtige strategische Position halten.\n\nSie müssen vernichtet werden.", sourceObjective = "Tötet 10 Grabhüter der Shan'ze, Seelenreißer der Shan'ze oder Donnerrufer der Shan'ze.", completion = "Exzellent. Ihr habt den Mogu eine Lektion verpasst, die sie nicht so schnell vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32528] = { id = 32528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Krypta", description = "Jeden Tag finden wir weitere Relikte im Hof der Knochen.\n\nVor Kurzem haben wir zwischen den Grabsteinen in einer der tiefsten Krypten diese Schriftrolle gefunden.\n\nIch glaube, dass mit dieser Zauberformel bis in die Totenwelt gerufen werden kann. Und wenn meine Mogukenntnisse mich nicht täuschen, würde ich sagen, dass man sie im letzten Raum der Halle der Ehrwürdigen benutzen soll.\n\nWärt Ihr bereit, meine Theorie zu testen?", sourceObjective = "Benutzt die Zauberformel von Gura in der Halle der Ehrwürdigen und besiegt dann Gura den Zurückgeforderten.", progress = "Wie ist es gelaufen?", completion = "Oh ja, Ihr habt soeben meine Theorie bestätigt! Danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32529] = { id = 32529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Donners", description = "Auf dem Friedhof, in den tiefsten Ruinen der westlichen Krypta, laden die mächtigsten Zauberer des Donnerkönigs einen Blitzableiter mit knisternder Elektrizität auf.\n\nWir vermuten, dass mit dieser Waffe unsere Festung auf der Violetten Erhebung zerstört werden soll.\n\nWir dürfen keine Zeit verlieren. Ihr müsst das Ritual sofort stoppen.", sourceObjective = "Unterbrecht das Ritual der Donnerrufer der Shan'ze.", completion = "Ihr übertrefft meine Erwartungen immer wieder, {class}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32530] = { id = 32530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutvergießer", description = "Mir ist ein verstörender Bericht zu Ohren gekommen, {class}.\n\nGanz in der Nähe, im Hof der Knochen, bringen die Mogu ihre Gefangenen zu einem General namens \"Kaida der Blutvergießer\".\n\nIch erspare Euch die Details, aber er lebt dafür, seine Opfer zu foltern.\n\nDieses Monster muss aufgehalten werden. Solltet Ihr seiner Klinge zum Opfer fallen, wünsche ich Euch einen raschen Tod.", sourceObjective = "Tötet Kaida den Blutvergießer.", progress = "Die Mogu sind zu unvorstellbaren Grausamkeiten fähig.", completion = "Ich freue mich zu hören, dass dieser Mistkerl tot ist. Ihr habt uns allen einen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32531] = { id = 32531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die steinerne Eroberung", description = "Im Hof der Knochen führen die Zauberer des Donnerkönigs finstere Rituale durch.\n\nUm ihre Truppen zu verstärken, hauchen die Seelenreißer der Shan'ze uralten Steinstatuen die Geister der Lebenden ein.\n\nSind diese Steineroberer einmal zum Leben erweckt, werden sie furchterregende Gegner auf dem Schlachtfeld sein.\n\nWir müssen ihr Ritual unterbrechen, bevor diese Statuen erweckt werden können.", sourceObjective = "Unterbrecht das Ritual des uralten Steineroberers im Haupttempel im Hof der Knochen.", progress = "Es ist mir ein Rätsel, wie die Mogu leblosem Stein Leben einhauchen können, aber mit genug Studien werden vielleicht auch wir diese Macht eines Tages verstehen.", completion = "Eine gute Verteidigung ist genauso effektiv wie eine starke Offensive. Ein Feind weniger, um den wir uns Gedanken machen müssen.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32532] = { id = 32532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch nie wieder!", description = "Habt Ihr die Geister gesehen, die im Friedhof umherwandern?\n\nDas sind auferstandene Urahnen, die in diese Welt zurückgerufen wurden.\n\nWerden sie verärgert, greifen sie schnell und lautlos an, und es werden von Tag zu Tag mehr.\n\nSie gehören nicht hierher. Vernichtet sie und schickt sie zurück in das Totenreich.", sourceObjective = "Tötet 15 auferstandene Urahnen.", progress = "Wie ist die Lage auf dem Friedhof?", completion = "Wunderbare Arbeit, {class}. Das wird unserer Offensive sehr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32533] = { id = 32533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marmor, Stein und Qilen bricht", description = "Unser Angriff auf den Hof der Knochen schreitet voran. Unsere Fortschritte sind weiterhin langsam, aber messbar.\n\nLeider haben wir mehrere Berichte über steinerne Qilenstatuen erhalten, die ohne Vorwarnung zum Leben erwachen. Diese Qilen sind zu gefährlich, um sie zu ignorieren.\n\nBegebt Euch in den Hof der Knochen und zerstört alle Qilenstatuen, die Ihr finden könnt.", sourceObjective = "Zerstört 8 Grabwächter.", completion = "Ich freue mich zu hören, dass Ihr die Qilen in tausend winzige Stücke zerschlagen habt. Sie sind für meine Arbeit hier auf der Insel kaum mehr als ein Ärgernis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32534] = { id = 32534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Skumklingen-Bedrohung", description = "Die Ihgalukklamm wimmelt von Saurok. Diese Bestien greifen meine Männer an, breiten ihre Krankheit auf Wild und Wasser in der Nähe aus und stören unsere Arbeit.\n\nDünnt ihre Reihen aus, {name}. Wenn die Horde diese Insel erst unter Kontrolle hat, können wir uns über permanentere Lösungen Gedanken machen.", sourceObjective = "Tötet 10 Saurok der Skumklingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32535] = { id = 32535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Skumklingen-Bedrohung", description = "Die Ihgalukklamm wimmelt von Saurok. Diese Bestien greifen meine Männer an, breiten ihre Krankheit auf Wild und Wasser in der Nähe aus und stören unsere Arbeit.\n\nDünnt ihre Reihen aus, {name}. Wenn die Allianz diese Insel erst unter Kontrolle hat, können wir uns über permanentere Lösungen Gedanken machen.", sourceObjective = "Tötet 10 Saurok der Skumklingen.", completion = "Eines Tages wird diese Insel der Allianz gehören. Ich kann nur hoffen, dass sie vorher frei von Saurok sein wird.\n\n<Modera verzieht das Gesicht.>\n\nWenigstens greifen sie auch die Horde an.", sourceObjectiveStatus = "unverified-source-field" }
quests[32536] = { id = 32536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saurok manipulieren", description = "Ich habe drei Magister in die Ihgalukklamm geschickt, um die Saurok zu überwachen und sie – wenn möglich – gegen die Mogu aufzuwiegeln. Ihr müsst sie für mich finden und herausfinden, ob sie Versorgung oder Hilfe benötigen.\n\nSie sind wahrscheinlich versteckt. Haltet nach schimmernden Lichtsäulen im Dorf der Saurok Ausschau.", sourceObjective = "Meldet Euch bei Magister Yalis, Magister Lyanis und Magistrix Sanal.", progress = "Viel Glück, {name}.", completion = "<Die Erzmagierin hört Eurem Bericht aufmerksam zu.>\n\nIch verstehe. Danke für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32537] = { id = 32537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekonstruktion", description = "Die Saurok testen unaufhörlich unsere Grenzen aus, und normalerweise können unsere Konstrukte sie zurückschlagen. Einige Konstrukte wurden jedoch besiegt und zurück in die Ihgalukklamm geschleppt.\n\nIch will diese Konstrukte zurück. Keine schleimige Echse wird das Eigentum des Silberbunds stehlen, während ich hier das Sagen habe.", sourceObjective = "Beschafft die vier gestohlenen Konstrukte des Silberbunds wieder.", progress = "Hmpf… Saurok.\n\n<Modera spuckt.>", completion = "Schon besser.\n\nDanke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32538] = { id = 32538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abscheuliche Opfer", description = "Einige der stärksten Geisterbinder führen schändliche Riten für ihre abscheulichen Götter durch.\n\nWir haben eine Methode entwickelt, um ihre Altäre zu zerstören. Der schwierige Teil der Aufgabe wird also sein, lebend zu jedem der Altäre zu gelangen.\n\nWagt Euch ins Innerste von Za'Tual und zerstört ihre Altäre.", sourceObjective = "Zerstört die Opferaltäre der Zandalari.", progress = "Mir ist klar, dass ich Euch um etwas Gefährliches bitte, aber es ist notwendig.", completion = "{class}, die Zerstörung dieser Altäre wird die Zandalari zwingen, die abscheulichsten ihrer Opferungen zu unterbrechen. Der Dank aller hier ist Euch gewiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[32539] = { id = 32539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Opfergaben", description = "Die Geisterbinder der Zandalari bringen finstere Opfer, um ihre Götter zu besänftigen, und dabei töten sie unsere Leute.\n\nZerstört alle Opfergaben, die Ihr in Za'Tual finden könnt, um die Rate ihrer finsteren Opfer zu verlangsamen.", sourceObjective = "Zerstört 6 Zandalariopfergaben.", completion = "Ohne die Opfergaben werden sie erst mehr sammeln müssen, bevor die Opfer weitergehen können. Danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32540] = { id = 32540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorboten der Loa", description = "Wenn Ihr etwas Zeit in Za'Tual verbringt, werdet Ihr wahrscheinlich sehen, dass aus einem ihrer Zelte eine Form des reinen Bösen austritt.\n\nBitte, reist zum Trolllager und setzt diesen unaussprechlichen Ritualen ein Ende.", sourceObjective = "Tötet 2 Vorboten der Loa.", completion = "Die meisten, die Zeuge solcher Rituale werden, kehren nie zurück. Diejenigen, die zurückkehren, sind oft erschüttert. Ihr, {name}, scheint von Euren unglaublichen Taten kaum bewegt zu sein. Ich bin beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32541] = { id = 32541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer zukünftigen Bedrohung vorbeugen", description = "Es schmerzt mich, an die Qualen zu denken, die die armen Himmelskreischer ertragen müssen, wenn die Zandalari sie zu Kriegsmaschinen erziehen.\n\nDie Jungtiere sind recht schreckhaft und fliegen fort, wenn man sich ihnen auch nur nähert. Bitte verscheucht einige von ihnen, bevor die Zandalari sie verderben können.", sourceObjective = "Erschreckt 12 Himmelskreischerjungtiere, indem Ihr in ihre Nähe lauft.", completion = "Willkommen zurück, {race}. Die Jungtiere, die Ihr erschreckt habt, werden ohne ihre Häscher ein besseres Leben leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32542] = { id = 32542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff mit chirurgischer Präzision", description = "Die Geisterbinder der Zandalari opfern ihren Göttern, die Bestienrufer unterwerfen unschuldige Himmelskreischer ihrem Willen und die Jaguarkrieger wagen sich von Tag zu Tag näher an uns heran.\n\nMacht diese Bedrohungen in Za'Tual unschädlich, {race}, und Ihr werdet sehen, wie die Zandalari geschwächt werden.", sourceObjective = "Tötet 3 Geisterbinder der Zandalari, 3 Bestienrufer der Zandalari und 3 Jaguarkrieger der Zandalari.", completion = "Nun, da ein paar weitere Exemplare ihrer bedrohlicheren Sippschaft tot sind, werden die Zandalari vielleicht zögern, wenn sie sich das nächste Mal mit uns anlegen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32543] = { id = 32543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahren von Za'Tual", description = "Die Zandalari sind ernstzunehmende Gegner – gefährlicher als viele, die wir in der Vergangenheit bekämpft haben. Aber auch Ihr seid <ein ernstzunehmender Gegner/eine ernstzunehmende Gegnerin>, {name}.\n\nBetretet Za'Tual und zeigt ihnen, wie gefährlich Ihr wirklich seid.", sourceObjective = "Tötet 12 Trolle in Za'Tual.", completion = "{name}, ich weiß Eure Hilfe gegen die Zandalari zu schätzen. Mir ist klar, dass es aussieht, als könnten wir die Flut nicht eindämmen, aber Eure Bemühungen zeigen ihre Wirkung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32544] = { id = 32544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreischen vor Qualen", description = "Einer der Himmelskreischer in Za'Tual wird einem Folterritual unterzogen. Sein Wille wird für immer gebrochen, damit er seinen Meistern dient.\n\nTötet diejenigen, die die Kreatur solchen Qualen unterziehen, und wir können nur hoffen, dass sie sich wieder in den Himmel schwingen wird.", sourceObjective = "Befreit den gepeinigten Himmelskreischer.", progress = "Habt Ihr die Kreatur befreit?", completion = "Ich hoffe, diese Kreatur hat die Intelligenz zu wissen, wer sie gerettet hat. Es scheint mir, als wäre sie ein gefährlicher Gegner, wenn sie sich bedroht fühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32545] = { id = 32545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bewohner von Ihgaluk", description = "Die Skumklingen bedrohen unsere Leute, aber mit unverhohlenem Gemetzel zu reagieren, wäre eine Überreaktion.\n\nEine vernünftigere Reaktion auf diese Bedrohung wäre es, einige ihrer Stammesanführer zu töten. So erleiden sie weniger Blutvergießen und werden dennoch unsere Grenzen respektieren.", sourceObjective = "Tötet einen Schläger der Skumklingen, einen Saurierpriester der Skumklingen und einen Meerdrachen der Skumklingen.", completion = "Ich kenne den wahren Preis von Blutvergießen. Ich kenne den Preis des Krieges.\n\nEs wäre einfacher, unsere Angreifer blind zu massakrieren, bis sie aufgeben. Aber wäre das richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[32546] = { id = 32546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur leichte Aufräumarbeiten", description = "Das ist keine glamouröse Aufgabe. Lasst mich ganz direkt sein.\n\nDie Saurok der Skumklingen häufen all ihren Dreck in einem Tümpel mitten in ihrem Dorf auf. Dieser Dreck ist so konzentriert und ranzig, dass er sich zu einer bewegten, belebten Masse entwickelt hat.\n\nDie Saurok können ihren Drecktümpel ja gern behalten, aber da er sich außerhalb des Dorfes ausbreitet würde ich sagen, dass es an der Zeit ist einzuschreiten.", sourceObjective = "Zerstreut 75 Dreckstücke, indem Ihr den wabernden Dreck in der Ihgalukklamm tötet.", completion = "Gut gemacht, {name}. Wenn ich Euch so ansehe, werde ich plötzlich ganz stolz auf das moderne Abwassersystem Dalarans.", sourceObjectiveStatus = "unverified-source-field" }
quests[32547] = { id = 32547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die krabbelnde Decke auf Ihgaluk", description = "Ach ja, Schaben! Ich habe in der Beutebucht mal eine Schabe als Haustier gekauft.\n\nSchaben saugen Krankheiten auf wie kleine Schwämme, und dann verbreiten sie sie, so schnell sie nur laufen können. Und sie können ziemlich weit laufen.\n\nDie Ihgalukklamm wimmelt von den Dingern, und sie verteilen den Dreck der Skumklingen über die ganze Insel. Zerquetscht so viele von ihnen wie Ihr nur könnt, während Ihr dort seid.", sourceObjective = "Zerquetscht 75 Ihgaluk-Schaben.", completion = "Jedes bisschen hilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[32548] = { id = 32548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrotten lassen", description = "Die Saurok der Skumklingen verzehren nicht alles Fleisch, das sie erjagen. Sie behalten große Teile davon zurück, die in Stapeln neben ihren Behausungen verrotten und so Ungeziefer anziehen und Krankheiten ausbreiten.\n\nWir können nicht zulassen, dass die Saurok ihre Krankheiten außerhalb der Ihgalukklamm verbreiten. Beseitigt alles überschüssige Fleisch, das Ihr finden könnt.", sourceObjective = "Zerstört 3 faulige Fleischhaufen.", completion = "Würden sie stehen bleiben, wären diese Haufen weggeworfener Fleischreste eine perfekte Brutstätte für Krankheiten.\n\nWäre ich noch im Sektor der Krankheitsverbreitung tätig, würde ich in Betracht ziehen, sie selbst zu benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32549] = { id = 32549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Haut eines Saurok", description = "Die Ihgalukklamm ist ein gefährlicher Ort. Glücklicherweise stärkt Euch die Magie der Kirin Tor den Rücken.\n\nIch kann Euch in einen Saurok verwandeln.\n\nIch werde jetzt die erste Hälfte der Illusion auf Euch wirken. Danach solltet Ihr sofort zur Ihgalukklamm gehen und einen Skumklingensaurok töten. Sobald das erledigt ist, werde ich Euch kontaktieren und die zweite Hälfte vollenden.", sourceObjective = "Begebt Euch zur Ihgalukklamm und tötet einen Skumklingensaurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32550] = { id = 32550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verechst und zugenäht", description = "In den Bestienpferchen werdet Ihr einige der besten Bestienzähmer des Zandalarimilitärs finden. Sie sind darauf trainiert, mit Axt, Tier und Klauen zu töten. Dort bilden sie ihre Reiterschaft aus.\n\nIhr müsst für uns alle Zandalari töten, die Ihr in den Bestienpferchen findet, bevor sie ihre berittenen Monstrositäten hinaus aufs Schlachtfeld schicken können.", sourceObjective = "Bezwingt 10 Trolle der Zandalari in den Bestienpferchen.", completion = "Diese Trolle haben finstere Magien verwendet um ihre Ziele zu erreichen. Keine Geduld, keine Ehre. Mit ihrer Vernichtung habt Ihr der Welt heute einen großen Gefallen getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[32551] = { id = 32551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compyknüppler", description = "Die Raptoren und Sauriden der Zandalari stellen eine erhebliche Bedrohung für unsere Truppen dar. Sie sind hervorragende Jäger und können ihre Beute über große Entfernungen verfolgen. Zudem enden ihre Angriffe oft tödlich, wenn sie ihre Opfer überraschen können.\n\nIch möchte, dass Ihr Euch in die Bestienpferche begebt und ihre Zahl verringert. Wir müssen sicherstellen, dass sie sterben, bevor ihre Ausbildung abgeschlossen wurde.", sourceObjective = "Tötet 5 Raptoren und 10 abgerichtete Sauriden in den Bestienpferchen.", completion = "Kurz nach unserer Ankunft hier haben wir drei gute Soldaten verloren. Im Schlaf von Sauriden getötet, die sich in ihr Zelt geschlichen hatten. In manchen Nächten höre ich noch immer ihre Schreie.", sourceObjectiveStatus = "unverified-source-field" }
quests[32552] = { id = 32552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loasaurus", description = "Die Zandalari haben einen Weg gefunden, um Loa an ihre Bestien zu binden, was den Tieren beeindruckende und tödliche Kräfte verleiht.\n\nWir müssen das beenden.\n\nSucht in den Bestienpferchen nach einem Loasprecher und tötet ihn. Es sollte Euch möglich sein, einen zu finden, wenn Ihr Ausschau nach ihren leuchtenden Reittieren haltet.\n\nDiese Untaten dürfen einfach nicht weitergehen.", sourceObjective = "Bezwingt einen Loasprecher.", progress = "Ich habe immer geglaubt, dass die Loa nur ein simpler Aberglaube von Trollen seien. Diese Zandalari stecken voller Überraschungen.", completion = "Gut gemacht, Champion. Diese Bestien sind stark genug. Sie müssen nicht auch noch von einem verärgerten Geist besessen sein, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[32553] = { id = 32553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorhorn vs. Teufelssaurier", description = "Wir haben eine Gelegenheit, die Kriegsmaschinerie der Zandalari ins Stocken zu bringen und gleichzeitig etwas Spaß zu haben.\n\nIn diesen Bestienpferchen werden ein Teufelssaurier und ein Terrorhorn mit Rüstung ausgestattet, während ihr Geist den Zaubern der Zandalari unterworfen ist.\n\nGeht in das Lager und unterbrecht eines dieser Bindungsrituale. Es ist egal welches, tötet einfach nur diejenigen, die sich bemühen die Kreatur zu binden. Das sollte genügen, um das voll gerüstete Tier auf Verwüstungstour durch ihr Lager zu schicken. Dann lehnt Euch einfach zurück und genießt das Spektakel.", sourceObjective = "Unterbrecht ein Bindungsritual, indem Ihr alle Trolle tötet, die ein starrsinniges Terrorhorn oder einen widerspenstigen Teufelssaurier umringen.", progress = "Und, wofür habt Ihr Euch entschieden – Teufelssaurier oder Terrorhorn?", completion = "Es gibt wenige Dinge auf der Welt, die unterhaltsamer sind, als eine urzeitliche Bestie dabei zu beobachten, wie sie durch ein feindliches Lager wütet.\n\nWenn die Zeiten nicht so finster wären, würde ich es erwägen, Karten für eine solche Veranstaltung zu verkaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32554] = { id = 32554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurierstark", description = "Die Zandalari verwenden eine ganze Batterie von Fetischen und Amuletten, um ihre Wildtiermenagerie im Zaum zu halten.\n\nBei diesem Spielchen können wir mitspielen.\n\nIch möchte, dass Ihr einige dieser Fetische auftreibt und ihre Wirkung auf die verschiedenen Tiere in den Bestienpferchen untersucht.\n\nNotiert Euch aufmerksam, wie welches Tier auf welchen Fetisch reagiert. Gebt Eure Untersuchungen dann an mich weiter.\n\nVielleicht kann uns das genau den Vorteil verschaffen, den wir gegen die Zandalari benötigen.", sourceObjective = "Findet Saurierfetische und wendet sie auf 5 Raptoren, Compys, Himmelskreischer oder Terrorhörner in den Bestienpferchen an.", completion = "Sehr interessante Resultate. Ich bin mir sicher, dass es hier einen Magier gibt, der sich auf die Details stürzen wird. Ich für meinen Teil bin froh, mich am Geschrei von Trollen zu erfreuen, die von ihren eigenen Bestien angegriffen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32555] = { id = 32555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jahrhundertwachen", description = "Innerhalb der Gesellschaft der Zandalari sind Opferungen gang und gäbe. Jedoch gibt es eine Kuriosität im Kreis dieser barbarischen Rituale: Freiwillige. Sie betrachten es als große Ehre!\n\nSelbst die Schwachen wollen noch ihren Teil beitragen, selbst wenn dies bedeutet, dass sie ihr Leben geben müssen. Ihre Seelen werden an die Wachen gebunden, die Ihr hier herumlaufen seht. Eingesperrt, um ihrem Volk zu Diensten zu sein.\n\nNehmt diesen Resonanzkristall. Entzieht den Wachen damit die ihnen innewohnenden Zandalarigeister, sobald sie zerstört wurden. Bringt den Kristall zu mir zurück, wenn Eure Aufgabe abgeschlossen ist.", sourceObjective = "Zerstört 5 geist-gebundene Wachposten und nutzt den Resonanzkristall, um die in ihnen gefangenen Zandalarigeister einzusammeln.", completion = "Das ist sehr interessant, {class}. Dieser Kristall summt geradezu von der gesammelten Wut seiner Gefangenen. Selbst nach all dieser Zeit hat sich ihre Ergebenheit nicht geschmälert.\n\nIch werde das weiter untersuchen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32556] = { id = 32556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissenssammlung", description = "Überall in diesem Gebiet liegen Artefakte der Zandalari herum. Ich würde lügen, würde ich behaupten, sie wären für mich von keinem Interesse. Ich bin von der Signifikanz dieser Objekte für die Rituale dieser Kultur fasziniert.\n\nJe besser wir unsere Feinde verstehen, desto besser sind wir darauf vorbereitet, ihnen gegenüberzutreten.\n\nWenn ich sie untersuchen soll, muss ich sie von Nahem begutachten. Bringt mir so viele Artefakte, wie Ihr finden könnt.", sourceObjective = "Sammelt in der Gegend um die Terrasse des Eroberers 6 Ritualartefakte ein.", progress = "Was habt Ihr mir gebracht, {class}?", completion = "Ein exzellenter Fund! Die Untersuchung der Stücke wird Zeit in Anspruch nehmen, dennoch besteht im Verstehen der Zandalari ein großer Gewinn.", sourceObjectiveStatus = "unverified-source-field" }
quests[32557] = { id = 32557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindeshänden entrissen", description = "Magie ist eine erschreckende Waffe, wenn sie von einem erfahrenen Nutzer angewandt wird. Eine Klinge jedoch ist selbst in unbedarften Händen eine große Bedrohung.\n\nDie Zandalari sind im Besitz von beeindruckenden Waffen, welche durch die Magie, mit der sie erfüllt sind, umso tödlicher werden. Wir sollten sie um diesen Vorteil erleichtern.\n\nStehlt so viele dieser Waffen, wie Ihr finden könnt.", sourceObjective = "Stehlt 7 loabeseelte Klingen von der Terrasse des Eroberers.", progress = "Was habt Ihr da draußen gefunden? Irgendetwas, das uns von Nutzen sein kann?", completion = "Exzellente Arbeit, {class}! Diese Waffen sind beeindruckend. Jetzt brauchen wir uns auf dem Schlachtfeld eine Sorge weniger machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32558] = { id = 32558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familienangelegenheit", description = "Die Aufseher der Terrasse des Eroberers sind zwei Brüder, Geisterbinder Tu'chek und Arkanital Ra'kul. Sie sind mächtige Magiewirker, die man nicht unterschätzen sollte.\n\nIhre Macht scheint den verzierten Masken zu entspringen, die sie tragen; Relikte, die von einer Generation an die nächste weitergegeben wurden. Jeder Besitzer erfüllte sie mit der ihm eigenen Magie, bevor er sie weitergab.\n\nWir müssen uns um die Brüder kümmern und ihre Masken zerstören, bevor sie in die falschen Hände geraten.", sourceObjective = "Entwendet Geisterbinder Tu'chek und Arkanital Ra'kul auf der Terrasse des Eroberers die Maske des dunklen Mystikers und die Maske des Geisterrufers.", progress = "Wo sind die Masken?", completion = "Es ist wirklich ein Jammer, dass diese Masken zerstört werden müssen. Ich hätte diese urtümliche Magie gern untersucht. Jedoch ist es besser sie zu vernichten, statt sie möglicherweise zu Werkzeugen der Horde werden zu lassen.\n\nGute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32559] = { id = 32559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantische Zerstörung", description = "Die Zandalari verehren die Loatiergeister, die sie oft zu ihrer Unterstützung anrufen. Möglicherweise versuchen sie, diese Geister an einen mächtigen Golem zu binden. Das Endresultat wäre katastrophal.\n\nIch habe einen Späher vorgeschickt, um mehr Informationen zu sammeln. Jedoch glaube ich, dass bei dieser Aufgabe Eure Expertise vonnöten ist.\n\nDieses Ritual muss unterbrochen werden, um jeden Preis!", sourceObjective = "Zerstört Wächter Tak'u auf der Terrasse des Eroberers.", completion = "Es war ein glücklicher Umstand, dass Ihr da wart, um einzuschreiten, {class}. Wer weiß, welchen Schaden dieser Golem hätte anrichten können, wäre er nicht aufgehalten worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32560] = { id = 32560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrt das Geheimnis", description = "Die Zandalari hier stellen eine Bedrohung für unseren Feldzug dar, {class}.\n\nIhre Art der Magie ist eine Abscheulichkeit. Sie vermengen die Mächte des Arkanen mit dem Dunkel der Schatten, beinahe ungeachtet der Konsequenzen.\n\nWir können dies nicht gestatten - weder, dass sie ihre volle Stärke erlangen, noch dass die Horde die Geheimnisse ihrer dunklen Magie erlent.\n\nIhre Ränge müssen ausgedünnt werden. Ich überlasse diese Aufgabe Euch.", sourceObjective = "Tötet 8 Trolle der Zandalari jeglicher Art auf der Terrasse des Eroberers.", completion = "Gut gemacht, {class}. Je mehr Zandalari wir töten desto geringer wird die Chance, dass ihre Magie der Horde in die Hände fällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32561] = { id = 32561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konkurrierende Magie", description = "Einer meiner Seher hat einen der Anführer der Zandalari in der Nähe des zentralen Turmes ausgemacht. Er muss beseitigt werden.\n\nWärt Ihr gewillt, das für mich zu tun, {class}?", sourceObjective = "Tötet Arkanwirker Jor'guva.", sourceObjectiveStatus = "unverified-source-field" }
quests[32562] = { id = 32562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposante Bedrohung", description = "Einer meiner Späher ist mit einem Bericht über einen Moguanführer zurückgekehrt, den er unter dem zentralen Turm entdeckt hat. Er muss beseitigt werden.\n\nWürdet Ihr das für mich tun, {class}?", sourceObjective = "Tötet Horgak den Versklaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[32563] = { id = 32563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindlicher Übergriff", description = "Wir haben unten am Strand einen Kriegstrupp der Zandalari entdeckt, knapp hinter diesen Mauern. Wir müssen ihn vernichten, bevor wir ins Lager zurückkehren.\n\nSeid Ihr dieser Aufgabe gewachsen?", sourceObjective = "Tötet Nurkala, den Kriegsanführer der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32564] = { id = 32564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg der Zandalari", description = "Wir haben einen Anführer der Zandalari auf der mittleren Treppe entdeckt. Wir müssen ihn vernichten, bevor wir ins Lager zurückkehren.\n\nKönnt Ihr das übernehmen?", sourceObjective = "Tötet Arkanwirker Jor'guva.", sourceObjectiveStatus = "unverified-source-field" }
quests[32565] = { id = 32565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindlicher Übergriff", description = "Wir haben einen Kriegstrupp der Zandalari am Strand entdeckt. Wir müssen ihn vernichten, bevor wir ins Lager zurückkehren.\n\nWärt Ihr bereit, das für mich zu erledigen?", sourceObjective = "Tötet Nurkala, den Kriegsanführer der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32567] = { id = 32567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bestienpferche", description = "Ich möchte keinen weiteren dieser Bestienreiter der Zandalari unsere Verteidigung durchbrechen sehen!\n\nIch habe Späherhauptmann Daelin und einige Kriegsmagier zu den Bestienpferchen im Nordwesten von hier entsandt. Ihre Mission ist es, die Belagerungs- sowie berittenen Einheiten der Zandalari zu infiltrieren und zu stören. Ich möchte, dass Ihr zu ihnen stoßt und sie von Eurer Erfahrung profitieren lasst.\n\nHaltet die Augen offen, dann solltet Ihr das Schimmern ihrer Tarnzauber sehen können.", sourceObjective = "Findet Späherhauptmann Daelin in den Bestienpferchen.", completion = "Heute jagen wir die Jäger!", sourceObjectiveStatus = "unverified-source-field" }
quests[32568] = { id = 32568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit zum Ausruhen", description = "Seit unserem Eintreffen haben wir hier viel erreicht, jetzt ist jedoch noch nicht die Zeit, um sich auszuruhen. Durch Eure Anstrengungen wurde es uns möglich, zum obersten Geschoss der Festung des Donnerkönigs durchzubrechen.\n\nNun rufe ich Euch erneut herbei, um unseren Feldzug fortzuführen. Meldet Euch bei Späherhauptmann Daelin auf der Terrasse des Eroberers. Er hat weitere Befehle für Euch.", sourceObjective = "Findet Späherhauptmann Daelin auf der Terrasse des Eroberers.", completion = "Die Zandalari hier dürfen nicht unterschätzt werden, {class}. Mächtige Magien durchdringen diesen Ort.\n\nWir müssen mit großer Sorgfalt vorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32569] = { id = 32569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtspur im Dunkel", description = "Im Düstermoor gibt es eine Art finstere Magie, die selbst unsere magische Beleuchtung auslöscht, und so fällt es unseren Spähern schwer, den Weg zu finden.\n\nWenn Ihr durch den Sumpf reist, entzündet bitte alle Fackeln die Ihr findet, sodass unsere Männer sich orientieren können. Vielleicht findet auch Ihr so Euren Weg zurück.", sourceObjective = "Entzündet 8 Fackeln im Düstermoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32570] = { id = 32570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt Späherberichte" }
quests[32571] = { id = 32571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pterrorschwingen verleihen Flügel", description = "Ich habe gerade den Bericht erhalten, dass eine weitere junge Pterrorschwinge im Düstermoor gesehen wurde.\n\nWir müssen so viele von ihnen einfangen, wie wir nur können. Sie sind vielleicht der Schlüssel zum Fliegen auf dieser Insel.", sourceObjective = "Fangt ein wildes Pterrorschwingenjungtier.", progress = "Eine große Düsternis liegt auf dieser Insel…", completion = "Wunderbar! Ich werde ihn an unseren Pfleger weiterreichen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[32572] = { id = 32572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schlaflose Legion", description = "Die Shan'ze erwecken eine Armee aus den Statuen in der Mitte der Insel, eine Armee, die unsere Verteidigung Tag und Nacht auf die Probe stellt. Zerstört jede wandelnde Statue, die Ihr zu Gesicht bekommt. Unsere Verteidiger wären Euch sehr dankbar.", sourceObjective = "Tötet 6 animierte Krieger.", completion = "Eure Anstrengungen werden gewürdigt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32573] = { id = 32573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde unter dem Turm", description = "Im Düstermoor halten sich Mogu auf, die die Statuenarmee beim Turm erwecken. Vereesa will, dass sie sterben. Ich glaube, Ihr könnt das erledigen.", sourceObjective = "Tötet 7 Mogu der Shan'ze im Düstermoor.", completion = "Gut gemacht, {class}. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32574] = { id = 32574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schaudernde Moor", description = "Im Sumpf lebt eine riesige Bestie. Sie hat uns noch nicht angegriffen, aber ich würde nicht darauf wetten, dass dies auch so bleibt.\n\nTötet sie, bevor sie der Hunger dazu antreibt, unsere Verteidigungsstellungen anzugreifen.", sourceObjective = "Tötet den mächtigen Teufelssaurier.", completion = "Mit Euch sollte man es sich nicht verscherzen. Ich bin sicher, dass ich in Zukunft Verwendung für Euch haben werde.\n\nKommt morgen zu mir zurück, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32575] = { id = 32575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koloss der Zandalari", description = "Die Trolle haben eines ihrer riesigen Konstrukte an die südliche Straße geschickt, sodass es uns den Weg über die Insel blockiert. Sorgt dafür, dass die Straße geräumt wird, {class}.", sourceObjective = "Zerstört den Koloss der Zandalari.", completion = "Wenn ich Euch eine Aufgabe gebe, wird sie erledigt.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32576] = { id = 32576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konkurrierende Magie", description = "Einer der Seher hat einen Anführer der Zandalari in der Nähe des zentralen Turms ausgemacht. Er muss beseitigt werden.\n\nWärt Ihr gewillt, das für mich zu tun, {class}?", sourceObjective = "Tötet Arkanwirker Jor'guva.", sourceObjectiveStatus = "unverified-source-field" }
quests[32577] = { id = 32577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposante Bedrohung", description = "Einer von Vereesas Spähern hat einen Moguanführer unter dem zentralen Turm entdeckt. Er muss beseitigt werden.\n\nWärt Ihr gewillt das für mich zu tun, {class}?", sourceObjective = "Tötet Horgak den Versklaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[32578] = { id = 32578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen", description = "Die Späher haben zwischen den Knochen westlich der Ihgalukklamm einen gefährlichen Zandalari entdeckt. Ich brauche jemand Fähigen, der dafür sorgt, dass er beseitigt wird. Traut Ihr Euch das zu?", sourceObjective = "Tötet Zur'chaka den Knochenformer.", completion = "Es ist gut, einen Mann in der Nähe zu haben, auf den ich mich verlassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[32579] = { id = 32579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konkurrierende Magie", description = "Die Späher haben diesseits von Za'Tual einen gefährlichen Zandalari entdeckt. Ich brauche jemand Fähigen, der dafür sorgt, dass er beseitigt wird. Traut Ihr Euch das zu?", sourceObjective = "Tötet Arkanwirker Jor'guva.", completion = "Eure Fähigkeiten sind in der Tat beeindruckend. Danke, dass Ihr das für mich getan habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32580] = { id = 32580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindlicher Übergriff", description = "Uns wurde von einem Kriegstrupp der Zandalari am Strand berichtet, nördlich unserer Stellung. Er muss aufgespürt und vernichtet werden.\n\nSeid Ihr gewillt, das für uns zu tun, {class}?", sourceObjective = "Tötet Nurkala, den Kriegsanführer der Zandalari.", completion = "Ihr habt unseren Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32581] = { id = 32581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imposante Bedrohung", description = "Die Seher haben in der Nähe des zentralen Turms einen Anführer der Mogu entdeckt. Er muss sterben, bevor er einen Angriff gegen unsere Stellung anzettelt.\n\nKönnt Ihr Euch für uns darum kümmern?", sourceObjective = "Tötet Horgak den Versklaver.", completion = "Eine Bedrohung weniger an unserer Türschwelle. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32582] = { id = 32582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenregen", description = "Wir haben einen Anführer der Zandalari oben an der zentralen Treppe entdeckt. Wir müssen ihn eliminieren, bevor wir ins Lager zurückkehren.\n\nSeid Ihr zu dieser Tat bereit?", sourceObjective = "Tötet Zur'chaka den Knochenformer.", sourceObjectiveStatus = "unverified-source-field" }
quests[32583] = { id = 32583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg der Zandalari", description = "Wir haben einen Anführer der Zandalari oben an der zentralen Treppe entdeckt. Wir müssen ihn eliminieren, bevor wir ins Lager zurückkehren.\n\nKönnt Ihr Euch um ihn kümmern?", sourceObjective = "Tötet Arkanwirker Jor'guva.", sourceObjectiveStatus = "unverified-source-field" }
quests[32584] = { id = 32584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindlicher Übergriff", description = "Wir haben unten am Strand einen Kriegstrupp der Zandalari entdeckt, knapp hinter diesen Mauern. Wir müssen ihn vernichten, bevor wir ins Lager zurückkehren.\n\nSeid Ihr dieser Aufgabe gewachsen?", sourceObjective = "Tötet Nurkala, den Kriegsanführer der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32585] = { id = 32585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindlicher Übergriff", description = "Wir haben einen Kriegstrupp der Zandalari am Strand entdeckt. Wir müssen ihn vernichten, bevor wir ins Lager zurückkehren.\n\nWärt Ihr bereit, das für mich zu erledigen?", sourceObjective = "Tötet Nurkala, den Kriegsanführer der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32586] = { id = 32586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Maximalkondensator", description = "Die Minen nördlich von hier sind ein empfindlicher Teil der Versorgungslinie der Mogu. Sie benutzen riesige, mit Blitzen verzauberte Bohrer, um das Erz zu fördern.\n\nWenn Ihr die Bohrer manipulieren könntet, wären sie so gut wie zerstört und die Waffenfabrikation der Mogu würde wesentlich verlangsamt werden.\n\nOh, noch etwas – tötet auch denjenigen, der dort unten das Sagen hat, alles klar?", sourceObjective = "Zerstört 3 Blitzbohrer in den Blitzaderminen und tötet Metallfürst Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32587] = { id = 32587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede voraus!", description = "Die Schmiede liegt vor Euch und mit ihr das Herz der Moguschmiedekunst.\n\nEin wenig weiter befindet sich der Mogutorwächter, der den Schlüssel zum nächsten Teil der Stadt in seinen Händen hält.\n\nZeit für den Vorstoß!", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment von Fleischschmied Hoku auf der Insel des Donners ein.", progress = "Nun?", completion = "Gute Arbeit. Was Ihr heute getan habt, bringt uns einen Schritt näher an unser endgültiges Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32588] = { id = 32588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Geheimdienst Ihrer Magietät", description = "Auf Befehl von Jaina selbst versuchten einige unserer Agenten, sich hinter die Linien der Mogu zu schleichen – um herauszufinden, was in der Mine vor sich geht.\n\nSie wurden gefangen und werden wer weiß wie schrecklichen Foltern ausgesetzt.\n\nIhr müsst sie befreien und denjenigen töten, der sie gefangen hält. Wir lassen niemanden zurück!", sourceObjective = "Rettet die drei gefangenen Agenten der Kirin Tor aus der Blitzadermine und tötet Metallfürst Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32589] = { id = 32589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensblut", description = "Späher haben dieses seltsame Konstrukt ausgegraben, das in den Blitzaderminen verborgen lag. Eine Geheimwaffe des Donnerkönigs, kein Zweifel.\n\nVielleicht besteht eine Chance, diese Entdeckung zu unserem Vorteil zu nutzen. Wenn wir das Konstrukt reanimieren können, können wir es studieren. Und noch wichtiger: Wir können seine Schwächen aufdecken.\n\nGeht zum Thron des Donners und nutzt diesen Kristall, um etwas von der Essenz einzufangen, die diese Konstrukte animiert.\n\nKehrt zu mir zurück, wenn die Aufgabe abgeschlossen ist.", sourceObjective = "Benutzt den abgestimmten Kristall, um dem dunklen Animus auf dem Thron des Donners die Reste des Animus zu entziehen.", progress = "Wart Ihr beim Abschluss unserer Anstrengung erfolgreich?", completion = "Exzellente Arbeit, {class}! Dies ist in der Tat eine dunkle Magie. Wir müssen noch viel lernen, wenn wir hier erfolgreich sein wollen.\n\nJetzt gilt es nur zu hoffen, dass wir diese Kreatur reanimieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[32590] = { id = 32590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft mich oben", description = "Da ist jemand, den Ihr treffen solltet. Der Kronprinz von Sturmwind höchstselbst hat diesem bescheidenen Gasthof vor Kurzem einen Besuch abgestattet. Ich habe meinen Wachen befohlen, ihn gegen jegliche Angriffe der Horde zu verteidigen – Ich möchte keine unnötige Aufmerksamkeit auf mich ziehen.\n\nEr und ich haben uns über die Lage der Welt unterhalten, zum Beispiel über die Schlacht an der Südküste, sein Treffen mit Garrosh und den kommenden Angriff auf den Donnerkönig.\n\nKommt! Lasst uns oben weiterreden...", sourceObjective = "Trefft Furorion im zweiten Stock der Taverne im Nebel an der Verhüllten Treppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32591] = { id = 32591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des ersten Kaiserreiches", description = "Zweitausend Jahre lang haben die Mogu dieses ganze Land beherrscht. Ihr Regime war so brutal, dass sein Name nie laut ausgesprochen wird: Die Pandaren nennen es entweder das \"alte Königreich\" oder \"Erste Dynastie\".\n\nDer Donnerkönig war sein Begründer und erster Kaiser. Er sammelte große Macht an dem Ort, der nun die Insel des Donners ist.\n\nSeine Zeit ist vorbei, {name}. Wir sollten etwas von seiner Macht für uns selbst beanspruchen. Tragt für mich Mogurelikte vom Thron des Donners zusammen und sammelt etwas Trillium – ich habe einen Plan!", sourceObjective = "Sammelt 20 Geheimnisse des Kaiserreichs und 40 Trilliumbarren.", sourceObjectiveStatus = "unverified-source-field" }
quests[32592] = { id = 32592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich brauche einen Champion", description = "Ihr seid ein großartiges Beispiel für Euer Volk, {race}. Aber ich brauche jemand besonderen. Ich habe große Pläne. Und um sie durchzuführen, brauche ich einen Champion, der mein Feuer an alle Enden der Welt trägt.\n\nSeid Ihr dieser Champion?\n\nBeweist es mir auf der Insel des Donners! Vernichtet alle Mogu, Zandalari oder Saurok, die Ihr finden könnt. Beeindruckt mich!", sourceObjective = "Erlangt einen ehrfürchtigen Ruf beim Schwarzen Prinzen, indem Ihr feindliche Mogu, Zandalari und Saurok auf der Insel des Donners besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32593] = { id = 32593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Donnerschmiede", description = "Alles ist vorbereitet, {name}, und ich habe Euch als meinen Champion gewählt.\n\nAls nächstes müssen wir die legendäre Donnerschmiede des Donnerkönigs selbst infiltrieren! Ihr und Eure Fraktion müsst vordringen, bis die Donnerschmiede geöffnet ist – wenn sie das noch nicht ist.\n\nHabt Ihr die Schmiede einmal infiltriert, trefft mich dort. Macht Euch auf einen Kampf gefasst!", sourceObjective = "Kämpft Euch durch die Insel des Donners, bis die Donnerschmiede zugänglich wird. Trefft Euch vor der Donnerschmiede mit Furorion und schließt seine Aufgabe ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[32594] = { id = 32594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Sturmfürsten", description = "Unser nächstes Ziel ist es, diese Waffe mit dem Blut eines Halbgottes zu härten, der mit den Mächten des Donnerkönigs beseelt ist.\n\nMeine Agenten berichten mir, dass der Mogu namens Shan'Bu eine solche Kreatur erschafft, mit dem Ziel, sie die Zitadelle des Donnerkönigs bewachen zu lassen.\n\nGreift Nalak den Sturmfürsten an, sobald sich Eure Fraktion zu den Haupttoren durchgekämpft hat, und stoßt diese Lanze in seine Seite. Die Kreatur wird alles in ihrer Macht stehende tun, um Euch aufzuhalten – handelt schnell und tötet Nalak, während die Lanze noch in seinem Fleisch steckt!", sourceObjective = "Kämpft Euch durch die Insel des Donners, bis der Innenhof zugänglich wird. Beschafft Euch eine gehärtete Blitzlanze, indem Ihr Nalak dem Sturmfürsten die Lanze in den Leib stoßt und lang genug überlebt, um ihm seine Macht zu entziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32595] = { id = 32595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Himmels", description = "Erinnert Ihr Euch an des Steinmetz' Torheit, die Hügelkuppe östlich von hier, wo wir uns schon einmal getroffen haben?\n\nIch werde die Blitzlanze benutzen, um etwas besonderes zu erschaffen, und hier drin kann ich das ganz bestimmt nicht tun.\n\nTrefft mich oben auf des Steinmetz' Torheit, damit wir unsere Siege gemeinsam feiern können!", sourceObjective = "Trefft Euch auf des Steinmetz' Torheit an der Verhüllten Treppe mit Furorion, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32596] = { id = 32596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos der Titanen", description = "Langsam sehe ich das große Ganze und was die Mogu mit den Titanen zu tun haben. Aber jede Antwort wirft nur weitere Fragen auf!\n\nDie einzige Möglichkeit, dieses Rätsel zu lösen, ist es, im Palast des Donnerkönigs so viele Informationsschnipsel wie möglich über die Titanen zu sammeln. Vernichtet den Donnerkönig und seine Diener und sammelt so viele Runensteine der Titanen, wie Ihr nur könnt!", sourceObjective = "Sammelt 12 Runensteine der Titanen von Schlachtzugsbossen in den Hallen der Fleischformer und der Spitze der Stürme.", sourceObjectiveStatus = "unverified-source-field" }
quests[32597] = { id = 32597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Donnerkönigs", description = "Der Donnerkönig. Seit zwölftausend Jahren tot, nur damit die Stimme der Zandalari ihn wieder zum Leben erwecken kann. Ohne Zweifel hat die Macht der Titanen seinen abstoßenden Leichnam konserviert.\n\nEine Macht, die von Rechts wegen mir gebührt.\n\n{name}! Bringt mir das Herz des Donnerkönigs. Es wird mir gehören, und sobald ich es habe, wird ihn niemand je wieder zum Leben erwecken können.\n\nBringt es mir, {class}. Bringt mir sein kaltes, totes Herz!", sourceObjective = "Tötet den Donnerkönig in den Hallen des Donners und nehmt sein Herz an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32598] = { id = 32598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Abrechnung", description = "Der Donnerkönig ist tot, und seine Werkzeuge der Unterdrückung werden von der Allianz und der Horde für deren eigene Zwecke ausgeschlachtet.\n\nWir kommen nun zum Höhepunkt der Pandarenkampagne. Höllschreis Intrigen haben den Zorn der Allianz auf ihn gezogen – aber was noch wichtiger ist: Er hat die Einheit der Horde zerschlagen. Wie die Pandaren sagen: \"Der Wok ist heiß.\" Es braut sich etwas zusammen, und alle unsere Anstrengungen hängen davon ab.\n\nIch brauche Zeit, um Pläne zu schmieden. Sprecht mit mir, sobald Eure Fraktion bereit ist, zu handeln!", sourceObjective = "Sprecht mit Furorion im oberen Stock der Taverne im Nebel an der Verhüllten Treppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32599] = { id = 32599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukunftssicherung", description = "Man sagt, dass die Macht des Donnerkönigs direkt aus einer verborgenen Quelle in seinem Palast stammt.\n\nSelbst wenn er besiegt wird, könnte ein neuer Tyrann, vielleicht Garrosh, diese Magie für schreckliche Zwecke nutzen.\n\nAllerdings nur, wenn wir ihm nicht zuvorkommen!\n\nBringt meinen Stab in die Spitze der Stürme. Wenn Lei Shen besiegt ist, stellt meinen Stab in die Mitte seiner Estrade.\n\nWir werden den Rest seiner Macht entziehen und sicherstellen, dass sie in unseren Händen bleibt.", sourceObjective = "Besiegt den Donnerkönig in der Spitze der Stürme und benutzt Antonidas' Stab, um seiner Estrade die restliche Macht zu entziehen.", progress = "Wenn Lei Shens Macht erst mit meinem Stab verbunden ist, werden wir unbesiegbar sein.", completion = "Ihr habt uns gerade einen Vorteil verschafft, {name}. Man wird sich an Eure Werke hier erinnern.\n\nGarrosh wird für seine Taten büßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32600] = { id = 32600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zandalariprophezeiung", sourceObjective = "Bringt \"Die Zandalariprophezeiung\" zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand:", completion = "Es ist kein Wunder, dass die Zandalari hierhergekommen sind. Sie brauchen eine neue Heimat, und ich bin mir sicher, dass ihre Moguverbündeten ihnen genau das versprochen haben.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32601] = { id = 32601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnergrollen", sourceObjective = "Bringt \"Donnergrollen\" zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand:", completion = "Alles, was wir über Lei Shen wissen, basiert auf dunklen Legenden, die uns aus grauer Vorzeit überliefert wurden. Ich habe mich oft gefragt, ob im Verlauf der Zeit die Kräfte Lei Shens nicht vielleicht etwas hochgespielt wurden. Aber Eure Nachforschungen lassen eher den Schluss zu, dass wir die wahre Macht des Donnerkönigs sogar unterschätzt haben. Dies sind wahrlich dunkle Zeiten.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32602] = { id = 32602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götter und Monster", sourceObjective = "Bringt \"Götter und Monster\" zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand:", completion = "Die Ergebnisse Eurer Nachforschungen beunruhigen mich sehr. Aber sie werfen etwas Licht auf einen Sachverhalt, den wir schon lange zu ergründen suchen: \"Woher kommen die Mogu? Und warum waren sie solche Tyrannen?\"\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich es für Euch nacherzählen soll, so zeigt einfach auf den richtigen Band in Eurer Privatsammlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32603] = { id = 32603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen", description = "Habt Ihr je das große Buch der pandarischen Fabeln gelesen? Die Pandaren reichen diese Geschichten an ihre Kinder weiter – die Geschichte von der Grille und dem Falken, oder der langsamen Schildkröte – um sie Lektionen zu lehren, die ihnen in ihrem späteren Leben von Nutzen sein werden. Was nur wenige Kinder wissen ist, dass es diese Kreaturen wirklich gibt, hier in Pandaria! Obwohl die Geschichten ihrer Reisen erfunden sind, sind sie doch mächtige Bewohner dieser Welt. Solltet Ihr ihnen auf Euren Reisen begegnen, könnt Ihr die Macht Eurer Haustiere gegen diese sagenumwobenen Gestalten auf die Probe stellen.", sourceObjective = "Besiegt die Elite-Kampfhaustiere der pandarischen Fabelwelt.", completion = "Ihr habt sie alle gefunden? Unglaublich! Die Geschichten sind also doch wahr! Vielleicht werdet Ihr ja die nächste große pandarische Fabel schreiben, über Eure eigene unglaubliche Reise!", sourceObjectiveStatus = "unverified-source-field" }
quests[32604] = { id = 32604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen, Buch I", description = "Die Geschichten von Ka'wi dem Schlinger, Nitun, Kafi und Dos-Ryga werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", sourceObjective = "Besiegt Ka'wi den Schlinger, Nitun, Kafi und Dos-Ryga.", completion = "Ich verneige mich vor Euch, der weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32605] = { id = 32605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtile Anregung", description = "Die Saurok mögen widerlich sein, aber wir haben einen gemeinsamen Feind: die Mogu. Und ich würde lieber Saurok losschicken, um Mogu zu töten, als meine eigenen Männer aufs Spiel zu setzen. Rammt diese Stangenwaffen in die Schädel der Saurok. Facht die Rivalitäten unserer Feinde an, und Ihr könnt damit Leben der Horde retten.", sourceObjective = "Stoßt Moguwaffen in die Leichen von 9 Saurok der Skumklingen.", completion = "Meisterlich, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32606] = { id = 32606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtile Anregung", description = "Die Saurok mögen widerlich sein, aber wir haben einen gemeinsamen Feind: die Mogu. Und ich würde lieber Saurok losschicken, um Mogu zu töten, als meine eigenen Männer aufs Spiel zu setzen. Rammt diese Stangenwaffen in die Schädel der Saurok. Facht die Rivalitäten unserer Feinde an, und Ihr könnt damit Leben der Allianz retten.", sourceObjective = "Stoßt Moguwaffen in die Leichen von 9 Saurok der Skumklingen.", completion = "Meisterlich, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32607] = { id = 32607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgedehnter Landgang", description = "Die Zandalari haben bereits begonnen, dieses Kriegsschiff zu reparieren, aber wir können es mit minimalem Aufwand untauglich halten.\n\nEntfernt einfach den neuen Kapitän von seinem Posten und stehlt die Schadensberichte des Schiffes aus dieser Werkstatt vor dem Gewölbe.\n\nKein Kapitän. Keine Reparaturen. Kein Kriegsschiff.", sourceObjective = "Stehlt die Werkstattsaufträge und tötet den neuen Kapitän des Kriegsschiffes der Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32608] = { id = 32608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer plündern", description = "Die Prall Gefüllte Kammer ist ein Hort von Lei Shens bösartigsten Waffen und gepriesensten Schätzen. Es dürfte nicht allzu überraschend sein, dass das oft ein und dasselbe ist.\n\nBesonders ein Artefakt, ein Amulett, das als das Halsband der Stürme bekannt ist, könnte uns dabei helfen, seine offensichtliche Herrschaft über Blitze zu verstehen.\n\nBrecht in die Kammer ein und tötet den Schatzmeister. Nehmt seinen Schlüssel und bergt das Amulett aus einer Truhe im hinteren Teil der Kammer.", sourceObjective = "Stehlt das Halsband der Stürme aus der Prall Gefüllten Kammer.", progress = "Die Stärke des Donnerkönigs ist legendär. Wir brauchen jeden Vorteil, den wir uns verschaffen können, wenn wir ihn besiegen wollen.", completion = "Was ist das? Eine Halskette? Was versucht Ihr - aaah, ich verstehe… Ein Relikt aus der Schatzkammer des Donnerkönigs! Faszinierend… Und mächtig.\n\nDie Kirin Tor werden es sicher verwahren. Bitte akzeptiert dies als Gegenleistung.", sourceObjectiveStatus = "unverified-source-field" }
quests[32609] = { id = 32609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltene Truhe, Tracking-Quest" }
quests[32610] = { id = 32610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltener Boss, Tracking-Quest" }
quests[32611] = { id = 32611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltener Drop, Tracking-Quest" }
quests[32613] = { id = 32613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesiger Dinosaurierknochen", progress = "Was habt Ihr für Ku'ma?", completion = "<Ku'ma zuckt mit den Schultern.>" }
quests[32614] = { id = 32614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr riesige Dinosaurierknochen", progress = "Gebt sie her! Gebt sie mir!", completion = "Knochen Knochen Knochen Knochen Knochen…" }
quests[32615] = { id = 32615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr riesige Dinosaurierknochen", progress = "Wer seid Ihr? Warum seid Ihr zurück? Hihihi…", completion = "Zu viele, nicht genug, nein nein… gebt sie alle Ku'ma…" }
quests[32616] = { id = 32616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Haufen riesige Dinosaurierknochen", progress = "<Ku'ma kichert irre und gestikuliert in Eure Richtung.>", completion = "Fürchtet Ihr den Tod? Hihi…" }
quests[32617] = { id = 32617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Berg riesiger Dinosaurierknochen", progress = "<Ku'ma beginnt, in seiner Höhle zu tanzen.>", completion = "<Ku'mas Kinnlade fällt beim Anblick so vieler Knochen herunter.>" }
quests[32618] = { id = 32618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Randal Weidmann im Holzfällerlager des Osttals im Wald von Elwynn. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Randal Weidmann.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt Katie Weidmann hier im Lager finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32621] = { id = 32621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerstahl", description = "Mit erfahrenem Blick erkennt Ihr, dass dieser Metallblock ein paar sehr ungewöhnliche Eigenschaften hat. Vielleicht sind irgendwo hier in der Nähe Hinweise auf seine wahre Natur?", sourceObjective = "Erkundet die Donnerschmiede, um die Geheimnisse des Donnerstahls zu erfahren.\n\nBereitgestellter Gegenstand:", completion = "Die Sprache ist zwar unverständlich, die Diagramme in diesem Buch geben ihre Geheimnisse jedoch Eurem geschulten, schmiedeerfahrenen Auge preis. Euch wird klar, dass Ihr, die Eigenschaften von Geistereisen manipulierend, ein Material von großer Macht herstellen könntet – vielleicht mächtig genug, um die Macht von Waffen nachzubilden und zu erhöhen, die schon seit langer Zeit in den Nebeln der Zeit verloren sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[32622] = { id = 32622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Introflug" }
quests[32626] = { id = 32626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loot Room Key Tracking Quest" }
quests[32627] = { id = 32627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgeladenes Moganit", description = "Wir haben jeden Tag Spione in die Basis der Sonnenhäscher geschickt. Einige davon mit dem Befehl, dem Feind aufgeladenes Moganit zu entwenden und es hierher zu bringen.\n\nSie sind nicht zurückgekehrt, obwohl ich belegen kann, dass sie die Basis der Sonnenhäscher verlassen haben.\n\nDurchkämmt den Dschungel zwischen hier und dort und findet alles aufgeladene Moganit, das vielleicht unterwegs verloren gegangen ist. Bringt es zu mir, und wir werden es zu verwenden wissen.", sourceObjective = "Beschafft ein Stück aufgeladenes Moganit und bringt es zu Kriegsmagier Yurias.", completion = "Gut gemacht, Champion. Dieses Artefakt wird in unseren Händen besser aufgehoben sein als in denen der Sonnenhäscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[32628] = { id = 32628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktische Manabomben", sourceObjective = "Bringt jeweils eine taktische Manabombe an einem Schiff der Sonnenhäscher, an den Seherkristallen und an der Brücke, die am weitesten im Inneren des Morgensucherkaps liegt, an.", completion = "Es schmerzt mich, auf solche Waffen zurückgreifen zu müssen, aber die Sonnenhäscher müssen den Preis ihrer Taten erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[32629] = { id = 32629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderwing Captured Tracking Quest" }
quests[32630] = { id = 32630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefingenieur Jards Tagebuch", description = "Was für eine ungewöhnliche Energiequelle. Wie sie wohl funktioniert? Und was könnte man mit ihr erschaffen?", sourceObjective = "Erkundet die Donnerschmiede, um die Geheimnisse des stabilisierten Blitzes zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[32631] = { id = 32631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Anerkennung", sourceObjective = "Eure Präsenz auf dem Schlachtfeld ist nicht zu leugnen. Ich möchte Euch dies als zusätzliche Anerkennung für Eure Leistungen überreichen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32632] = { id = 32632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Krieg geschaffen", description = "Manche Dinge werden gebaut, um mehrere Zwecke zu erfüllen. Manche Dinge werden mit nur einem Zweck gebaut: Zerstörung.\n\nEin gigantisches Konstrukt, das man den Pyrosternvernichter nennt, bewacht das Morgensucherkap. Es dient keinem anderen Zweck als der Zerstörung. Es muss zerlegt werden.", sourceObjective = "Tötet den Pyrosternvernichter.", completion = "Exzellente Arbeit, {race}. Das Problem bei Konstrukten ist, dass man sie immer wieder zusammenbauen kann.\n\nIch vermute, die Sonnenhäscher werden nicht lange brauchen, bis sie eine neue Todesmaschine gebaut haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32633] = { id = 32633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezaubernd", description = "Großmagister Rommath besitzt etwas, das ich haben will.\n\nEr hat ein sehr mächtiges Buch mitgebracht. Es wäre unserer Sache dienlich, wenn es sich nicht weiterhin in den Händen der Sonnenhäscher befände.\n\nFindet Rommaths Buch der Zaubersprüche und bringt es mir.", sourceObjective = "Beschafft Euch Rommaths Buch der Zaubersprüche am Morgensucherkap.", progress = "Habt Ihr das Buch gefunden?", completion = "Oh ja! Das ist es. Gut gemacht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32634] = { id = 32634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung zerstören", description = "Selbst die stärkste Verteidigung kann ihre Schwächen haben, {class}. Wir müssen nur die Schwäche in der Verteidigung der Sonnenhäscher finden und sie dann so gut wie möglich ausnutzen.\n\nSpäher berichten von Schutzzaubern um das Morgensucherkap herum. Sie sind mächtig, aber nicht tödlich.\n\nWenn wir sie deaktivieren, könnten wir ihre Aktivitäten genauer beobachten.", sourceObjective = "Zerstört 6 Schutzzauber der Sonnenhäscher am Morgensucherkap.", completion = "Exzellente Arbeit, {race}! Ich konnte einige meiner Späher hinter ihre Linien schmuggeln, bevor sie die Schutzzauber repariert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32635] = { id = 32635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt reichts aber mit den Bomben!", description = "Die Sonnenhäscher haben in unserem Lager taktische Manabomben platziert. Sie müssen auseinandergenommen werden, bevor sie detonieren.\n\nSucht sie an wichtigen Standorten, zum Beispiel bei unseren Vorräten. Geht sicher, dass Ihr sie alle findet und entschärft. Wir können uns hier keine Rückschläge leisten.", sourceObjective = "Entschärft die taktischen Manabomben bei den Allianzschiffen, dem Konstruktritual und den Vorräten auf der Violetten Erhebung.", completion = "Ich bin für Eure Mühen hier dankbar, {name}. Wir hätten so viel verloren, wenn Ihr diese Bomben nicht rechtzeitig entschärft hättet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32636] = { id = 32636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefesseltes Publikum", description = "Die Sonnenhäscher machen wirklich vor nichts halt, um zu bekommen, was sie wollen, {name}.\n\nMir wurde berichtet, dass mehrere Kirin Tor verschwunden sind. Ich vermute, dass die Sonnenhäscher etwas damit zu tun haben.\n\nHoffentlich sind sie nicht verletzt worden. Andernfalls wäre meine Rache schnell und entsetzlich. Ich verlasse mich darauf, das Ihr sie in einem Stück zurückbringt, aber bitte beeilt Euch.", sourceObjective = "Befreit 5 gefangene Kirin Tor am Morgensucherkap.", completion = "Ihr habt heute viele gerettet, {name}. Ich kann mir kaum vorstellen wie schrecklich es ist, inmitten so vieler Feinde eingefroren und hilflos zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32637] = { id = 32637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu stark", description = "Die Truppen der Sonnenhäscher sind in letzter Zeit mächtiger geworden. Ich vermute, dass hier Magie im Spiel ist, aber ich kann mir nicht sicher sein.\n\nIch glaube, es wäre klug, ihr Lager zu untersuchen und zu versuchen, die Quelle dieser zusätzlichen Macht zu finden.\n\nWenn Ihr sie gefunden habt, benutzt diesen Kristall um sie zu überladen und zu zerstören.", sourceObjective = "Zerstört 7 Manasammler der Sonnenhäscher am Morgensucherkap.", completion = "Sie benutzen also Objekte, die die Macht ihrer Truppen noch verstärken? Wir werden das genau im Auge behalten müssen.\n\nIch danke Euch für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32638] = { id = 32638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manadiebe", description = "Manchmal können selbst die kleinsten Kreaturen die größte Bedrohung darstellen.\n\nDie Sonnenhäscher haben Manawyrms mitgebracht. Sie mögen klein sein, aber sie können unsere Magiewirker im Kampf stark beeinträchtigen. Viele von ihnen haben auf die schwere Art gelernt, sie nicht zu unterschätzen.\n\nSie müssen beseitigt werden, und zwar schnell.", sourceObjective = "Tötet 9 Manawyrms der Sonnenhäscher.", completion = "Ihr habt heute gute Fortschritte gemacht, {class}. Aber glaubt mir, unsere Arbeit hier ist keineswegs getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[32639] = { id = 32639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Konstruktion", description = "Späher berichten, dass eine große Anzahl von Konstrukten vor dem Morgensucherkap patrouilliert.\n\nWenn sie in Frieden gelassen werden, werden sie eine beachtliche Bedrohung darstellen, falls die Sonnenhäscher einen Angriff unternehmen.\n\nEin Erstschlag ist die einzige Lösung. Wir werden sie zerstören, bevor sie uns angreifen können!", sourceObjective = "Zerstört 3 Konstrukte der Sonnenhäscher vor dem Morgensucherkap.", completion = "Gut gemacht, {class}. Solange wir die Anzahl der Konstruke klein halten, ist unser Sieg hier gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[32640] = { id = 32640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions des Donnerkönigs", description = "Diese Insel ist mit lauernder Gefahr von drei mächtigen Gruppen übersät, die nur darauf warten, uns zu überrumpeln. Meister der Blitze, uralte und mächtige Geister und urtümliche Monstrositäten der Zandalari.\n\nWenn Ihr einige der Ritualsteine der Shan'ze finden könnt, die auf der Insel verteilt sind, solltet Ihr in der Lage sein, diese mächtigen Gegner aus ihren Verstecken zu locken und sie zu bekämpfen.\n\nFindet und zerstört Mitglieder jeder Gruppe, damit sie destabilisiert bleiben, und ich werde Euch belohnen.", sourceObjective = "Findet Ritualsteine der Shan'ze, um das Blitzritual, das Geisterritual und das Urzeitliche Ritual an verschiedenen Orten auf der Insel des Donners durchzuführen und besiegt dann die beschworenen mächtigen Gegner.", completion = "Eure Fertigkeiten als {class} sind unstrittig. Ihr habt der Sache heute sehr geholfen. Ihr habt meinen Dank.\n\nUnd nun zu der Belohnung, die ich Euch versprochen habe…", sourceObjectiveStatus = "unverified-source-field" }
quests[32641] = { id = 32641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions des Donnerkönigs", description = "Diese Insel ist mit lauernder Gefahr von drei mächtigen Gruppen übersät, die nur darauf warten, uns zu überrumpeln. Meister der Blitze, uralte und mächtige Geister und urtümliche Monstrositäten der Zandalari.\n\nWenn Ihr einige der Ritualsteine der Shan'ze finden könnt, die auf der Insel verteilt sind, solltet Ihr in der Lage sein, diese mächtigen Gegner aus ihren Verstecken zu locken und sie zu bekämpfen.\n\nFindet und zerstört Mitglieder jeder Gruppe, damit sie destabilisiert bleiben, und ich werde Euch belohnen.", sourceObjective = "Findet Ritualsteine der Shan'ze, um das Blitzritual, das Geisterritual und das Urzeitliche Ritual an verschiedenen Orten auf der Insel des Donners durchzuführen und besiegt dann die beschworenen mächtigen Gegner.", progress = "Es gibt keine Zuflucht vor solchen Feinden. Wir schlagen zuerst zu und sie gar nicht.", completion = "Eure Fertigkeiten als {class} sind unstrittig. Ihr habt der Sache heute sehr geholfen. Ihr habt meinen Dank.\n\nUnd nun zu der Belohnung, die ich Euch versprochen habe…", sourceObjectiveStatus = "unverified-source-field" }
quests[32642] = { id = 32642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Herrschaftsoffensive I", description = "<Yoons Handschrift überzieht die Seite, doch er scheint mit gemischten Gefühlen geschrieben zu haben.>\n\nNormalerweise versuche ich, mich aus Konflikten herauszuhalten, aber Bestellung ist Bestellung. Da Ihr zur Horde gehört, habe ich beschlossen, diese Bestellung an Euch weiterzuleiten.\n\nDie Herrschaftsoffensive hat eine Fuhre Rotblütenlauch angefordert.\n\nDie Truppen dort können davon anscheinend gar nicht genug bekommen!", sourceObjective = "Pflanzt 8 Rotblütenlauchsamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32643] = { id = 32643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Herrschaftsoffensive II", description = "Sobald Euer Rotblütenlauch erntereif ist, müsst Ihr ihn nur noch für die Abholung einpacken.\n\nDenkt Euch nur, Euer Rotblütenlauch wird ein Teil des Kampfes Eurer Fraktion in Pandaria sein!", sourceObjective = "Erntet 8 reife Rotblütenlauchpflanzen und liefert 40 Rotblütenlauchstangen an die Herrschaftsoffensive.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft den Rotblütenlauch in die Kiste! In Kürze wird ein Vertreter der Herrschaftsoffensive eintreffen, um sie mitzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32644] = { id = 32644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff auf Shaol'mara", description = "Unsere Erkundungstätigkeiten an der Küste haben uns wertvolle Informationen über die Insel eingebracht, {class}.\n\nWir werden allerdings nichts erreichen, wenn wir nicht weiter auf das Festland vordringen.\n\nIch habe einen Trupp unserer besten Lufteinheiten zusammengestellt, um die Attacke einzuleiten.\n\nIch möchte, dass Ihr Euch diesem Angriff anschließt. Ein Champion wie Ihr könnte die Schlacht im kritischen Moment zu unseren Gunsten wenden.\n\nWenn Ihr bereit seid, mit dem Angriff zu beginnen, sprecht mit mir.", sourceObjective = "Schließt den Angriff auf Shaol'mara ab. Sprecht mit Jaina Prachtmeer, um den Angriff zu beginnen.", completion = "Ja! Ihr habt es geschafft, Champion!\n\nWir werden sein wie eine Flut, die über diese Insel hinwegbraust und unserem Volk eine neue Bestimmung bringt. Und Ihr, Held, seid an vorderster Front.", sourceObjectiveStatus = "unverified-source-field" }
quests[32645] = { id = 32645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Operation Schildwall I", description = "<Yoons Handschrift überzieht die Seite, doch er scheint mit gemischten Gefühlen geschrieben zu haben.>\n\nNormalerweise versuche ich, mich aus Konflikten herauszuhalten, aber Bestellung ist Bestellung. Da Ihr zur Allianz gehört, habe ich beschlossen, diese Bestellung an Euch weiterzuleiten.\n\nOperation Schildwall hat eine große Menge Hexenbeeren angefordert.\n\nIch bin mir nicht sicher, aber ich glaube, sie haben vor damit eine Art Waffe zu bauen.", sourceObjective = "Pflanzt 8 Hexenbeerensamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32646] = { id = 32646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Operation Schildwall II", description = "Sobald Eure Hexenbeeren erntereif sind, müsst Ihr sie nur noch für die Abholung einpacken.\n\nDenkt Euch nur, Eure Hexenbeeren werden ein Teil der Anstrengungen Eurer Fraktion in Pandaria sein!", sourceObjective = "Erntet 8 reife Hexenbeerenpflanzen und liefert 40 Hexenbeeren an Operation Schildwall.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft die Hexenbeeren in die Kiste! Ein Vertreter der Operation Schildwall wird in Kürze eintreffen, um sie abzuholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32647] = { id = 32647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Goldener Lotus I", description = "<Yoon hat seine Bestellung kurz gefasst.>\n\nDer Goldene Lotus hat eine große Menge weißer Rüben angefordert.\n\nSie haben etwas von ärgerlichen Geistern erwähnt, die in Nebelhauch ihr Unwesen treiben. Anscheinend mögen die Geister keine Rüben!", sourceObjective = "Pflanzt 8 weiße Rübensamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[32648] = { id = 32648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Goldener Lotus II", description = "Hoffen wir, dass dieses Gemüse geeignet ist!\n\nSobald Eure weißen Rüben erntereif sind, müsst Ihr sie nur noch für die Abholung einpacken.", sourceObjective = "Erntet 8 reife Rübenpflanzen und liefert 40 weiße Rüben an den Goldenen Lotus.", progress = "Die Kiste steht leer herum und wartet nur auf Eure Ernte.", completion = "Werft die weißen Rüben in die Kiste! In Kürze wird ein Vertreter des Goldenen Lotus eintreffen, um sie mitzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32649] = { id = 32649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Shado-Pan I", description = "<Yoons Handschrift erscheint fahrig. Er muss aufgeregt gewesen sein.>\n\nDie Shado-Pan wollen Gemüse von Euch! Was für eine Ehre!\n\nHeute Morgen kam eine Bestellung für Grünkohl an. Anscheinend machen sie daraus eine sehr schmackhafte Kohlsuppe.\n\nNur das Beste ist für die Shado-Pan gut genug!", sourceObjective = "Pflanzt 8 Grünkohlsamen auf dem Gehöft Sonnensang.", sourceObjectiveStatus = "unverified-source-field" }
